    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nstruct ListNode {\n  int val;\n  ListNode* next;\n};\n\n// Floyd's Tortoise and Hare: Returns cycle entrance node (or nullptr if acyclic)\nListNode* floyd_find_cycle_entrance(ListNode* head) noexcept {\n  ListNode* slow = head;\n  ListNode* fast = head;\n\n  // Phase 1: Find meeting point inside cycle\n  while (fast != nullptr && fast->next != nullptr) {\n    slow = slow->next;\n    fast = fast->next->next;\n    if (slow == fast) {\n      // Phase 2: Reset one pointer to head; advance both at speed 1\n      ListNode* finder = head;\n      while (finder != slow) {\n        finder = finder->next;\n        slow = slow->next;\n      }\n      return finder; // Exact cycle entrance!\n    }\n  }\n  return nullptr;\n}\n\n// Brent's Teleporting Turtle: Returns {cycle_entrance, cycle_length_lambda}\nstd::pair<ListNode*, std::size_t> brent_find_cycle(ListNode* head) noexcept {  // TODO (Step 1): Initialize state structures and base boundary conditions for brent_find_cycle\n  // TODO (Step 2): Execute core Pointer Chasing: Floyd's Tortoise-and-Hare vs Brent's Cycle Detection transition / loop invariant\n  // TODO (Step 3): Finalize and return verified result\n  return {};}\n\nint main() {\n  DESCRIBE(\"Pointer Chasing: Floyd's Tortoise-and-Hare vs Brent's Cycle Detection — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes ListNode state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes ListNode core algorithmic transition (O(mu + lambda))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies ListNode edge cases and space bound (Theta(mu + lambda))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nstruct ListNode {\n  int val;\n  ListNode* next;\n};\n\n// Floyd's Tortoise and Hare: Returns cycle entrance node (or nullptr if acyclic)\nListNode* floyd_find_cycle_entrance(ListNode* head) noexcept {\n  ListNode* slow = head;\n  ListNode* fast = head;\n\n  // Phase 1: Find meeting point inside cycle\n  while (fast != nullptr && fast->next != nullptr) {\n    slow = slow->next;\n    fast = fast->next->next;\n    if (slow == fast) {\n      // Phase 2: Reset one pointer to head; advance both at speed 1\n      ListNode* finder = head;\n      while (finder != slow) {\n        finder = finder->next;\n        slow = slow->next;\n      }\n      return finder; // Exact cycle entrance!\n    }\n  }\n  return nullptr;\n}\n\n// Brent's Teleporting Turtle: Returns {cycle_entrance, cycle_length_lambda}\nstd::pair<ListNode*, std::size_t> brent_find_cycle(ListNode* head) noexcept {\n  if (head == nullptr) return {nullptr, 0};\n\n  std::size_t power = 1;\n  std::size_t lambda = 1;\n  ListNode* tortoise = head;\n  ListNode* hare = head->next;\n\n  // Phase 1: Find cycle length lambda with 1 pointer chase per iteration!\n  while (hare != nullptr && tortoise != hare) {\n    if (power == lambda) {\n      tortoise = hare; // Teleport tortoise to hare\n      power *= 2;\n      lambda = 0;\n    }\n    hare = hare->next;\n    ++lambda;\n  }\n  if (hare == nullptr) return {nullptr, 0};\n\n  // Phase 2: Advance hare lambda steps ahead of head, then move both at speed 1\n  tortoise = head;\n  hare = head;\n  for (std::size_t i = 0; i < lambda; ++i) {\n    hare = hare->next;\n  }\n  while (tortoise != hare) {\n    tortoise = tortoise->next;\n    hare = hare->next;\n  }\n  return {tortoise, lambda};\n}\n\nint main() {\n  DESCRIBE(\"Pointer Chasing: Floyd's Tortoise-and-Hare vs Brent's Cycle Detection — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes ListNode state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes ListNode core algorithmic transition (O(mu + lambda))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies ListNode edge cases and space bound (Theta(mu + lambda))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
