    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass GapBuffer {\n  std::vector<char> buf_;\n  std::size_t gap_start_ = 0;\n  std::size_t gap_end_;\n\n  std::size_t gap_size() const noexcept { return gap_end_ - gap_start_; }\n\n  void expand_gap(std::size_t min_gap) {    // TODO (Step 1): Implement expand_gap(std::size_t min_gap)\n    // Maintain the Unrolled Linked Lists & Gap Buffers: Defeating Pointer Chasing invariant (O(B) time, O(1) space)\n  }\n\npublic:\n  explicit GapBuffer(std::size_t initial_cap = 64)\n      : buf_(initial_cap), gap_start_(0), gap_end_(initial_cap) {}\n\n  std::size_t size() const noexcept { return buf_.size() - gap_size(); }\n\n  // Move cursor (gap_start_) to logical position pos via overlapping-safe memmove\n  void move_cursor(std::size_t pos) noexcept {    // TODO (Step 2): Implement move_cursor(std::size_t pos)\n    // Maintain the Unrolled Linked Lists & Gap Buffers: Defeating Pointer Chasing invariant (O(B) time, O(1) space)\n  }\n\n  // O(1) amortized insertion at cursor\n  void insert_char(char c) {    // TODO (Step 3): Implement insert_char(char c)\n    // Maintain the Unrolled Linked Lists & Gap Buffers: Defeating Pointer Chasing invariant (O(B) time, O(1) space)\n  }\n\n  // O(1) backspace deletion before cursor\n  void backspace() noexcept {\n    if (gap_start_ > 0) --gap_start_;\n  }\n\n  // O(1) branchless random access to logical index i\n  char operator[](std::size_t i) const noexcept {\n    const std::size_t offset = (i >= gap_start_) ? gap_size() : 0;\n    return buf_[i + offset];\n  }\n};\n\nint main() {\n  DESCRIBE(\"Unrolled Linked Lists & Gap Buffers: Defeating Pointer Chasing — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes GapBuffer state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes GapBuffer core algorithmic transition (O(B))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies GapBuffer edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass GapBuffer {\n  std::vector<char> buf_;\n  std::size_t gap_start_ = 0;\n  std::size_t gap_end_;\n\n  std::size_t gap_size() const noexcept { return gap_end_ - gap_start_; }\n\n  void expand_gap(std::size_t min_gap) {\n    const std::size_t old_size = size();\n    const std::size_t new_cap = std::max(buf_.size() * 2, old_size + min_gap + 64);\n    std::vector<char> next_buf(new_cap);\n\n    // Copy prefix [0 .. gap_start_) to start of next_buf\n    std::memcpy(next_buf.data(), buf_.data(), gap_start_);\n    // Copy suffix [gap_end_ .. buf_.size()) to end of next_buf\n    const std::size_t suffix_len = buf_.size() - gap_end_;\n    const std::size_t new_gap_end = new_cap - suffix_len;\n    std::memcpy(next_buf.data() + new_gap_end, buf_.data() + gap_end_, suffix_len);\n\n    buf_ = std::move(next_buf);\n    gap_end_ = new_gap_end;\n  }\n\npublic:\n  explicit GapBuffer(std::size_t initial_cap = 64)\n      : buf_(initial_cap), gap_start_(0), gap_end_(initial_cap) {}\n\n  std::size_t size() const noexcept { return buf_.size() - gap_size(); }\n\n  // Move cursor (gap_start_) to logical position pos via overlapping-safe memmove\n  void move_cursor(std::size_t pos) noexcept {\n    assert(pos <= size());\n    if (pos < gap_start_) {\n      const std::size_t delta = gap_start_ - pos;\n      std::memmove(buf_.data() + gap_end_ - delta, buf_.data() + pos, delta);\n      gap_start_ -= delta;\n      gap_end_ -= delta;\n    } else if (pos > gap_start_) {\n      const std::size_t delta = pos - gap_start_;\n      std::memmove(buf_.data() + gap_start_, buf_.data() + gap_end_, delta);\n      gap_start_ += delta;\n      gap_end_ += delta;\n    }\n  }\n\n  // O(1) amortized insertion at cursor\n  void insert_char(char c) {\n    if (gap_start_ == gap_end_) expand_gap(1);\n    buf_[gap_start_++] = c;\n  }\n\n  // O(1) backspace deletion before cursor\n  void backspace() noexcept {\n    if (gap_start_ > 0) --gap_start_;\n  }\n\n  // O(1) branchless random access to logical index i\n  char operator[](std::size_t i) const noexcept {\n    const std::size_t offset = (i >= gap_start_) ? gap_size() : 0;\n    return buf_[i + offset];\n  }\n};\n\nint main() {\n  DESCRIBE(\"Unrolled Linked Lists & Gap Buffers: Defeating Pointer Chasing — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes GapBuffer state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes GapBuffer core algorithmic transition (O(B))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies GapBuffer edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
