    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass SkipList {\n  static constexpr int MAX_LEVEL = 16; // Supports up to 4^16 = 4.29B elements\n\n  struct Node {\n    int key;\n    int value;\n    int top_level;\n    Node* forward[1]; // Flexible trailing array allocated to size <code>top_level + 1</code>\n  };\n\n  Node* head_;\n  int cur_max_level_ = 0;\n  std::uint64_t rng_state_ = 0x853c49e6748fea9bULL;\n\n  static Node* allocate_node(int key, int val, int level) {    // TODO (Step 1): Implement allocate_node(int key, int val, int level)\n    // Maintain the Skip Lists: Probabilistic Multi-Level Indexing & O(log N) Search Proof invariant (O(log N) time, O(log N) space)\n    return nullptr;\n  }\n\n  // Fast xorshift64* PRNG sampling Geometric(p = 1/4) height\n  int random_level() noexcept {    // TODO (Step 2): Implement random_level()\n    // Maintain the Skip Lists: Probabilistic Multi-Level Indexing & O(log N) Search Proof invariant (O(log N) time, O(log N) space)\n    return 0;\n  }\n\npublic:\n  SkipList() {\n    head_ = allocate_node(-2147483648, 0, MAX_LEVEL - 1);\n  }\n\n  const int* find(int target) const noexcept {    // TODO (Step 3): Implement find(int target)\n    // Maintain the Skip Lists: Probabilistic Multi-Level Indexing & O(log N) Search Proof invariant (O(log N) time, O(log N) space)\n    return nullptr;\n  }\n\n  void insert(int key, int value) {\n    std::array<Node*, MAX_LEVEL> update{};\n    Node* curr = head_;\n\n    for (int i = cur_max_level_; i >= 0; --i) {\n      while (curr->forward[i] != nullptr && curr->forward[i]->key < key) {\n        curr = curr->forward[i];\n      }\n      update[i] = curr;\n    }\n\n    curr = curr->forward[0];\n    if (curr != nullptr && curr->key == key) {\n      curr->value = value;\n      return;\n    }\n\n    const int new_lvl = random_level();\n    if (new_lvl > cur_max_level_) {\n      for (int i = cur_max_level_ + 1; i <= new_lvl; ++i) {\n        update[i] = head_;\n      }\n      cur_max_level_ = new_lvl;\n    }\n\n    Node* inserted = allocate_node(key, value, new_lvl);\n    for (int i = 0; i <= new_lvl; ++i) {\n      inserted->forward[i] = update[i]->forward[i];\n      update[i]->forward[i] = inserted;\n    }\n  }\n};\n\nint main() {\n  DESCRIBE(\"Skip Lists: Probabilistic Multi-Level Indexing & O(log N) Search Proof — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SkipList state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SkipList core algorithmic transition (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SkipList edge cases and space bound (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass SkipList {\n  static constexpr int MAX_LEVEL = 16; // Supports up to 4^16 = 4.29B elements\n\n  struct Node {\n    int key;\n    int value;\n    int top_level;\n    Node* forward[1]; // Flexible trailing array allocated to size <code>top_level + 1</code>\n  };\n\n  Node* head_;\n  int cur_max_level_ = 0;\n  std::uint64_t rng_state_ = 0x853c49e6748fea9bULL;\n\n  static Node* allocate_node(int key, int val, int level) {\n    const std::size_t bytes = sizeof(Node) + static_cast<std::size_t>(level) * sizeof(Node*);\n    void* raw = ::operator new(bytes);\n    Node* node = static_cast<Node*>(raw);\n    node->key = key;\n    node->value = val;\n    node->top_level = level;\n    for (int i = 0; i <= level; ++i) node->forward[i] = nullptr;\n    return node;\n  }\n\n  // Fast xorshift64* PRNG sampling Geometric(p = 1/4) height\n  int random_level() noexcept {\n    int lvl = 0;\n    while (lvl < MAX_LEVEL - 1) {\n      rng_state_ ^= rng_state_ >> 12;\n      rng_state_ ^= rng_state_ << 25;\n      rng_state_ ^= rng_state_ >> 27;\n      if (((rng_state_ * 0x2545F4914F6CDD1DULL) >> 62) != 0) break; // 1/4 probability\n      ++lvl;\n    }\n    return lvl;\n  }\n\npublic:\n  SkipList() {\n    head_ = allocate_node(-2147483648, 0, MAX_LEVEL - 1);\n  }\n\n  const int* find(int target) const noexcept {\n    const Node* curr = head_;\n    for (int i = cur_max_level_; i >= 0; --i) {\n      while (curr->forward[i] != nullptr && curr->forward[i]->key < target) {\n        curr = curr->forward[i];\n      }\n    }\n    curr = curr->forward[0];\n    if (curr != nullptr && curr->key == target) return &curr->value;\n    return nullptr;\n  }\n\n  void insert(int key, int value) {\n    std::array<Node*, MAX_LEVEL> update{};\n    Node* curr = head_;\n\n    for (int i = cur_max_level_; i >= 0; --i) {\n      while (curr->forward[i] != nullptr && curr->forward[i]->key < key) {\n        curr = curr->forward[i];\n      }\n      update[i] = curr;\n    }\n\n    curr = curr->forward[0];\n    if (curr != nullptr && curr->key == key) {\n      curr->value = value;\n      return;\n    }\n\n    const int new_lvl = random_level();\n    if (new_lvl > cur_max_level_) {\n      for (int i = cur_max_level_ + 1; i <= new_lvl; ++i) {\n        update[i] = head_;\n      }\n      cur_max_level_ = new_lvl;\n    }\n\n    Node* inserted = allocate_node(key, value, new_lvl);\n    for (int i = 0; i <= new_lvl; ++i) {\n      inserted->forward[i] = update[i]->forward[i];\n      update[i]->forward[i] = inserted;\n    }\n  }\n};\n\nint main() {\n  DESCRIBE(\"Skip Lists: Probabilistic Multi-Level Indexing & O(log N) Search Proof — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SkipList state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SkipList core algorithmic transition (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SkipList edge cases and space bound (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
