    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass ExpressionEvaluator {\n  enum class Op : char { Add = '+', Sub = '-', Mul = '*', Div = '/', Pow = '^', Neg = '~', LParen = '(' };\n\n  static int precedence(Op op) noexcept {    // TODO (Step 1): Implement precedence(Op op)\n    // Maintain the Call Stacks, Dijkstra's Shunting-Yard Algorithm & AST Evaluation invariant (O(N log N) time, O(N) space)\n    return 0;\n  }\n\n  static bool is_right_assoc(Op op) noexcept {\n    return op == Op::Pow || op == Op::Neg;\n  }\n\n  static std::int64_t ipow(std::int64_t base, std::int64_t exp) noexcept {    // TODO (Step 2): Implement ipow(std::int64_t base, std::int64_t exp)\n    // Maintain the Call Stacks, Dijkstra's Shunting-Yard Algorithm & AST Evaluation invariant (O(N log N) time, O(N) space)\n    return {};\n  }\n\n  static void apply_op(std::vector<std::int64_t>& vals, Op op) noexcept {    // TODO (Step 3): Implement apply_op(std::vector<std::int64_t>& vals, Op op)\n    // Maintain the Call Stacks, Dijkstra's Shunting-Yard Algorithm & AST Evaluation invariant (O(N log N) time, O(N) space)\n  }\n\npublic:\n  static std::int64_t evaluate(std::string_view expr) {\n    std::vector<std::int64_t> vals;\n    std::vector<Op> ops;\n    bool expect_unary = true; // True at start, after '(', or after any operator\n\n    for (std::size_t i = 0; i < expr.size();) {\n      if (std::isspace(static_cast<unsigned char>(expr[i]))) {\n        ++i;\n        continue;\n      }\n      if (std::isdigit(static_cast<unsigned char>(expr[i]))) {\n        std::int64_t num = 0;\n        while (i < expr.size() && std::isdigit(static_cast<unsigned char>(expr[i]))) {\n          num = num * 10 + (expr[i] - '0');\n          ++i;\n        }\n        vals.push_back(num);\n        expect_unary = false;\n      } else if (expr[i] == '(') {\n        ops.push_back(Op::LParen);\n        expect_unary = true;\n        ++i;\n      } else if (expr[i] == ')') {\n        while (!ops.empty() && ops.back() != Op::LParen) {\n          apply_op(vals, ops.back());\n          ops.pop_back();\n        }\n        if (!ops.empty()) ops.pop_back(); // Pop '('\n        expect_unary = false;\n        ++i;\n      } else {\n        Op cur_op = static_cast<Op>(expr[i]);\n        if (cur_op == Op::Sub && expect_unary) {\n          cur_op = Op::Neg;\n        }\n        while (!ops.empty() && ops.back() != Op::LParen) {\n          const int p_top = precedence(ops.back());\n          const int p_cur = precedence(cur_op);\n          if (p_top > p_cur || (p_top == p_cur && !is_right_assoc(cur_op))) {\n            apply_op(vals, ops.back());\n            ops.pop_back();\n          } else {\n            break;\n          }\n        }\n        ops.push_back(cur_op);\n        expect_unary = true;\n        ++i;\n      }\n    }\n\n    while (!ops.empty()) {\n      apply_op(vals, ops.back());\n      ops.pop_back();\n    }\n    return vals.empty() ? 0 : vals.back();\n  }\n};\n\nint main() {\n  DESCRIBE(\"Call Stacks, Dijkstra's Shunting-Yard Algorithm & AST Evaluation — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes ExpressionEvaluator state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes ExpressionEvaluator core algorithmic transition (O(N log N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies ExpressionEvaluator edge cases and space bound (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass ExpressionEvaluator {\n  enum class Op : char { Add = '+', Sub = '-', Mul = '*', Div = '/', Pow = '^', Neg = '~', LParen = '(' };\n\n  static int precedence(Op op) noexcept {\n    switch (op) {\n      case Op::Add: case Op::Sub: return 1;\n      case Op::Mul: case Op::Div: return 2;\n      case Op::Pow:               return 3;\n      case Op::Neg:               return 4;\n      default:                    return 0;\n    }\n  }\n\n  static bool is_right_assoc(Op op) noexcept {\n    return op == Op::Pow || op == Op::Neg;\n  }\n\n  static std::int64_t ipow(std::int64_t base, std::int64_t exp) noexcept {\n    if (exp < 0) return 0;\n    std::int64_t res = 1;\n    while (exp > 0) {\n      if (exp & 1) res *= base;\n      base *= base;\n      exp >>= 1;\n    }\n    return res;\n  }\n\n  static void apply_op(std::vector<std::int64_t>& vals, Op op) noexcept {\n    if (op == Op::Neg) {\n      vals.back() = -vals.back();\n      return;\n    }\n    // CRITICAL: First popped is RIGHT operand, second popped is LEFT operand!\n    const std::int64_t rhs = vals.back(); vals.pop_back();\n    const std::int64_t lhs = vals.back(); vals.pop_back();\n    switch (op) {\n      case Op::Add: vals.push_back(lhs + rhs); break;\n      case Op::Sub: vals.push_back(lhs - rhs); break;\n      case Op::Mul: vals.push_back(lhs * rhs); break;\n      case Op::Div: vals.push_back(lhs / rhs); break;\n      case Op::Pow: vals.push_back(ipow(lhs, rhs)); break;\n      default: break;\n    }\n  }\n\npublic:\n  static std::int64_t evaluate(std::string_view expr) {\n    std::vector<std::int64_t> vals;\n    std::vector<Op> ops;\n    bool expect_unary = true; // True at start, after '(', or after any operator\n\n    for (std::size_t i = 0; i < expr.size();) {\n      if (std::isspace(static_cast<unsigned char>(expr[i]))) {\n        ++i;\n        continue;\n      }\n      if (std::isdigit(static_cast<unsigned char>(expr[i]))) {\n        std::int64_t num = 0;\n        while (i < expr.size() && std::isdigit(static_cast<unsigned char>(expr[i]))) {\n          num = num * 10 + (expr[i] - '0');\n          ++i;\n        }\n        vals.push_back(num);\n        expect_unary = false;\n      } else if (expr[i] == '(') {\n        ops.push_back(Op::LParen);\n        expect_unary = true;\n        ++i;\n      } else if (expr[i] == ')') {\n        while (!ops.empty() && ops.back() != Op::LParen) {\n          apply_op(vals, ops.back());\n          ops.pop_back();\n        }\n        if (!ops.empty()) ops.pop_back(); // Pop '('\n        expect_unary = false;\n        ++i;\n      } else {\n        Op cur_op = static_cast<Op>(expr[i]);\n        if (cur_op == Op::Sub && expect_unary) {\n          cur_op = Op::Neg;\n        }\n        while (!ops.empty() && ops.back() != Op::LParen) {\n          const int p_top = precedence(ops.back());\n          const int p_cur = precedence(cur_op);\n          if (p_top > p_cur || (p_top == p_cur && !is_right_assoc(cur_op))) {\n            apply_op(vals, ops.back());\n            ops.pop_back();\n          } else {\n            break;\n          }\n        }\n        ops.push_back(cur_op);\n        expect_unary = true;\n        ++i;\n      }\n    }\n\n    while (!ops.empty()) {\n      apply_op(vals, ops.back());\n      ops.pop_back();\n    }\n    return vals.empty() ? 0 : vals.back();\n  }\n};\n\nint main() {\n  DESCRIBE(\"Call Stacks, Dijkstra's Shunting-Yard Algorithm & AST Evaluation — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes ExpressionEvaluator state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes ExpressionEvaluator core algorithmic transition (O(N log N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies ExpressionEvaluator edge cases and space bound (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
