    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Simplified Redis-style Order-Statistic Skip List supporting O(log N) Rank & Select\nclass RankedSkipList {\n  static constexpr int MAX_LEVEL = 16;\n\n  struct LevelLink {\n    int next_idx = 0;       // 0 = nullptr sentinel\n    std::size_t span = 0;   // Number of level-0 nodes skipped by this link\n  };\n\n  struct Node {\n    double score = 0.0;\n    int member_id = 0;\n    int backward = 0;\n    std::array<LevelLink, MAX_LEVEL> level{};\n  };\n\n  std::array<Node, 4096> pool_{}; // Contiguous pool; index 0 is head sentinel\n  int pool_used_ = 1;\n  int max_lvl_ = 1;\n\n  static bool less_than(double s1, int m1, double s2, int m2) noexcept {\n    return (s1 < s2) || (s1 == s2 && m1 < m2);\n  }\n\npublic:\n  // O(log N) ZRANK: Returns 1-based rank of (score, member_id), or 0 if not found\n  std::size_t get_rank(double score, int member_id) const noexcept {    // TODO (Step 1): Initialize state structures and base boundary conditions for get_rank\n    // TODO (Step 2): Execute core Production Case Study: Redis ZSET (Listpack vs SkipList + Dict Dual Indexing) transition / loop invariant\n    // TODO (Step 3): Finalize and return verified result\n    return {};\n  }\n\n  // O(log N) ZRANGE by Rank: Retrieve node at 1-based positional rank target_rank\n  const Node* get_element_by_rank(std::size_t target_rank) const noexcept {\n    std::size_t traversed = 0;\n    int x = 0;\n    for (int i = max_lvl_ - 1; i >= 0; --i) {\n      while (pool_[x].level[i].next_idx != 0 &&\n             traversed + pool_[x].level[i].span <= target_rank) {\n        traversed += pool_[x].level[i].span;\n        x = pool_[x].level[i].next_idx;\n      }\n      if (traversed == target_rank) return &pool_[x];\n    }\n    return nullptr;\n  }\n};\n\nint main() {\n  DESCRIBE(\"Production Case Study: Redis ZSET (Listpack vs SkipList + Dict Dual Indexing) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes RankedSkipList state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes RankedSkipList core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies RankedSkipList edge cases and space bound (O(N log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Simplified Redis-style Order-Statistic Skip List supporting O(log N) Rank & Select\nclass RankedSkipList {\n  static constexpr int MAX_LEVEL = 16;\n\n  struct LevelLink {\n    int next_idx = 0;       // 0 = nullptr sentinel\n    std::size_t span = 0;   // Number of level-0 nodes skipped by this link\n  };\n\n  struct Node {\n    double score = 0.0;\n    int member_id = 0;\n    int backward = 0;\n    std::array<LevelLink, MAX_LEVEL> level{};\n  };\n\n  std::array<Node, 4096> pool_{}; // Contiguous pool; index 0 is head sentinel\n  int pool_used_ = 1;\n  int max_lvl_ = 1;\n\n  static bool less_than(double s1, int m1, double s2, int m2) noexcept {\n    return (s1 < s2) || (s1 == s2 && m1 < m2);\n  }\n\npublic:\n  // O(log N) ZRANK: Returns 1-based rank of (score, member_id), or 0 if not found\n  std::size_t get_rank(double score, int member_id) const noexcept {\n    std::size_t rank = 0;\n    int x = 0; // Start at head (index 0)\n    for (int i = max_lvl_ - 1; i >= 0; --i) {\n      while (pool_[x].level[i].next_idx != 0) {\n        const int nxt = pool_[x].level[i].next_idx;\n        if (less_than(pool_[nxt].score, pool_[nxt].member_id, score, member_id) ||\n            (pool_[nxt].score == score && pool_[nxt].member_id == member_id)) {\n          rank += pool_[x].level[i].span;\n          x = nxt;\n        } else {\n          break;\n        }\n      }\n      if (x != 0 && pool_[x].score == score && pool_[x].member_id == member_id) {\n        return rank;\n      }\n    }\n    return 0;\n  }\n\n  // O(log N) ZRANGE by Rank: Retrieve node at 1-based positional rank target_rank\n  const Node* get_element_by_rank(std::size_t target_rank) const noexcept {\n    std::size_t traversed = 0;\n    int x = 0;\n    for (int i = max_lvl_ - 1; i >= 0; --i) {\n      while (pool_[x].level[i].next_idx != 0 &&\n             traversed + pool_[x].level[i].span <= target_rank) {\n        traversed += pool_[x].level[i].span;\n        x = pool_[x].level[i].next_idx;\n      }\n      if (traversed == target_rank) return &pool_[x];\n    }\n    return nullptr;\n  }\n};\n\nint main() {\n  DESCRIBE(\"Production Case Study: Redis ZSET (Listpack vs SkipList + Dict Dual Indexing) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes RankedSkipList state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes RankedSkipList core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies RankedSkipList edge cases and space bound (O(N log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
