    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\ntemplate <std::totally_ordered T>\nclass FractionalCascadingCatalog {\npublic:\n    struct Node {\n        T val;\n        std::size_t real_idx;         // Index of lower_bound(val) in original list L_i\n        std::size_t next_cascade_idx; // Index of lower_bound(val) in next augmented list M_{i+1}\n    };\n\n    explicit FractionalCascadingCatalog(const std::vector<std::vector<T>>& lists, T sentinel_max)\n        : k_(lists.size()), sentinel_(sentinel_max), orig_(lists), aug_(k_) {      // TODO (Step 1): Initialize state structures and base boundary conditions for FractionalCascadingCatalog\n      // TODO (Step 2): Execute core Fractional Cascading: Searching K Sorted Lists in O(log N + K) transition / loop invariant\n      // TODO (Step 3): Finalize and return verified result\n    }\n\n    // Returns the lower_bound index in each of the k original lists in O(log N + k) time!\n    std::vector<std::size_t> query_all_lower_bounds(const T& q) const {\n        if (k_ == 0) return {};\n        std::vector<std::size_t> results(k_);\n\n        // 1. Single O(log N) binary search in top augmented list M_0\n        const auto& M0 = aug_[0];\n        auto it = std::lower_bound(M0.begin(), M0.end(), q,\n                                   [](const Node& nd, const T& val) { return nd.val < val; });\n        std::size_t cur = static_cast<std::size_t>(it - M0.begin());\n        results[0] = M0[cur].real_idx;\n\n        // 2. O(1) cascade step for each subsequent list 1 .. k - 1\n        for (std::size_t lvl = 0; lvl + 1 < k_; ++lvl) {\n            std::size_t next_pos = aug_[lvl][cur].next_cascade_idx;\n            const auto& M_next = aug_[lvl + 1];\n            // Because every 2nd element of M_{lvl+1} was promoted to M_lvl,\n            // the exact lower_bound in M_{lvl+1} is either next_pos - 1 or next_pos!\n            if (next_pos > 0 && !(M_next[next_pos - 1].val < q)) {\n                --next_pos;\n            }\n            cur = next_pos;\n            results[lvl + 1] = M_next[cur].real_idx;\n        }\n        return results;\n    }\n\nprivate:\n    std::size_t k_;\n    T sentinel_;\n    std::vector<std::vector<T>> orig_;\n    std::vector<std::vector<Node>> aug_;\n};\n\nint main() {\n  DESCRIBE(\"Fractional Cascading: Searching K Sorted Lists in O(log N + K) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes FractionalCascadingCatalog state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes FractionalCascadingCatalog core algorithmic transition (O(k log n))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies FractionalCascadingCatalog edge cases and space bound (O(log n + k))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\ntemplate <std::totally_ordered T>\nclass FractionalCascadingCatalog {\npublic:\n    struct Node {\n        T val;\n        std::size_t real_idx;         // Index of lower_bound(val) in original list L_i\n        std::size_t next_cascade_idx; // Index of lower_bound(val) in next augmented list M_{i+1}\n    };\n\n    explicit FractionalCascadingCatalog(const std::vector<std::vector<T>>& lists, T sentinel_max)\n        : k_(lists.size()), sentinel_(sentinel_max), orig_(lists), aug_(k_) {\n        if (k_ == 0) return;\n\n        // Build bottom-up from level k - 1 down to 0\n        for (std::ptrdiff_t lvl = static_cast<std::ptrdiff_t>(k_) - 1; lvl >= 0; --lvl) {\n            const auto& L = orig_[lvl];\n            std::vector<T> merged;\n            if (static_cast<std::size_t>(lvl) == k_ - 1) {\n                merged = L;\n            } else {\n                // Extract every 2nd element (indices 1, 3, 5, ...) of M_{lvl+1}\n                std::vector<T> promoted;\n                const auto& M_next = aug_[lvl + 1];\n                for (std::size_t j = 1; j < M_next.size(); j += 2) {\n                    if (M_next[j].val < sentinel_) promoted.push_back(M_next[j].val);\n                }\n                merged.resize(L.size() + promoted.size());\n                std::merge(L.begin(), L.end(), promoted.begin(), promoted.end(), merged.begin());\n                merged.erase(std::unique(merged.begin(), merged.end()), merged.end());\n            }\n            merged.push_back(sentinel_); // +infinity sentinel at end\n\n            // Populate real_idx (into L) and next_cascade_idx (into M_{lvl+1}) via two-pointer sweep\n            auto& M = aug_[lvl];\n            M.resize(merged.size());\n            std::size_t r_ptr = 0, c_ptr = 0;\n            for (std::size_t idx = 0; idx < merged.size(); ++idx) {\n                const T v = merged[idx];\n                while (r_ptr < L.size() && L[r_ptr] < v) ++r_ptr;\n                if (static_cast<std::size_t>(lvl) + 1 < k_) {\n                    const auto& M_next = aug_[lvl + 1];\n                    while (c_ptr + 1 < M_next.size() && M_next[c_ptr].val < v) ++c_ptr;\n                }\n                M[idx] = Node{v, r_ptr, c_ptr};\n            }\n        }\n    }\n\n    // Returns the lower_bound index in each of the k original lists in O(log N + k) time!\n    std::vector<std::size_t> query_all_lower_bounds(const T& q) const {\n        if (k_ == 0) return {};\n        std::vector<std::size_t> results(k_);\n\n        // 1. Single O(log N) binary search in top augmented list M_0\n        const auto& M0 = aug_[0];\n        auto it = std::lower_bound(M0.begin(), M0.end(), q,\n                                   [](const Node& nd, const T& val) { return nd.val < val; });\n        std::size_t cur = static_cast<std::size_t>(it - M0.begin());\n        results[0] = M0[cur].real_idx;\n\n        // 2. O(1) cascade step for each subsequent list 1 .. k - 1\n        for (std::size_t lvl = 0; lvl + 1 < k_; ++lvl) {\n            std::size_t next_pos = aug_[lvl][cur].next_cascade_idx;\n            const auto& M_next = aug_[lvl + 1];\n            // Because every 2nd element of M_{lvl+1} was promoted to M_lvl,\n            // the exact lower_bound in M_{lvl+1} is either next_pos - 1 or next_pos!\n            if (next_pos > 0 && !(M_next[next_pos - 1].val < q)) {\n                --next_pos;\n            }\n            cur = next_pos;\n            results[lvl + 1] = M_next[cur].real_idx;\n        }\n        return results;\n    }\n\nprivate:\n    std::size_t k_;\n    T sentinel_;\n    std::vector<std::vector<T>> orig_;\n    std::vector<std::vector<Node>> aug_;\n};\n\nint main() {\n  DESCRIBE(\"Fractional Cascading: Searching K Sorted Lists in O(log N + K) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes FractionalCascadingCatalog state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes FractionalCascadingCatalog core algorithmic transition (O(k log n))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies FractionalCascadingCatalog edge cases and space bound (O(log n + k))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
