    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nusing cd = std::complex<double>;\n\n// In-place Iterative Radix-2 Cooley-Tukey FFT (invert = false) and IFFT (invert = true)\nvoid fft_inplace(std::vector<cd>& a, bool invert) noexcept {  // TODO (Step 1): Initialize state structures and base boundary conditions for fft_inplace\n  // TODO (Step 2): Execute core Fast Fourier Transform (Cooley-Tukey FFT) & O(N log N) Polynomial Convolution transition / loop invariant\n  // TODO (Step 3): Finalize and return verified result}\n\n// Convolves two integer polynomials A and B in O(N log N) time\nstd::vector<std::int64_t> multiply_polynomials_fft(const std::vector<std::int64_t>& A,\n                                                   const std::vector<std::int64_t>& B) {\n    if (A.empty() || B.empty()) return {};\n    const std::size_t result_len = A.size() + B.size() - 1;\n    std::size_t n = 1;\n    while (n < result_len) n <<= 1;\n\n    std::vector<cd> fa(n, cd(0.0, 0.0)), fb(n, cd(0.0, 0.0));\n    for (std::size_t i = 0; i < A.size(); ++i) fa[i] = static_cast<double>(A[i]);\n    for (std::size_t i = 0; i < B.size(); ++i) fb[i] = static_cast<double>(B[i]);\n\n    fft_inplace(fa, false);\n    fft_inplace(fb, false);\n    for (std::size_t i = 0; i < n; ++i) {\n        fa[i] *= fb[i];\n    }\n    fft_inplace(fa, true);\n\n    std::vector<std::int64_t> result(result_len);\n    for (std::size_t i = 0; i < result_len; ++i) {\n        result[i] = static_cast<std::int64_t>(std::llround(fa[i].real()));\n    }\n    return result;\n}\n\nint main() {\n  DESCRIBE(\"Fast Fourier Transform (Cooley-Tukey FFT) & O(N log N) Polynomial Convolution — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes fft_inplace state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes fft_inplace core algorithmic transition (O(n))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies fft_inplace edge cases and space bound (Theta(n^2))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nusing cd = std::complex<double>;\n\n// In-place Iterative Radix-2 Cooley-Tukey FFT (invert = false) and IFFT (invert = true)\nvoid fft_inplace(std::vector<cd>& a, bool invert) noexcept {\n    const std::size_t n = a.size();\n\n    // 1. O(N) In-place Bit-Reversal Permutation\n    for (std::size_t i = 1, j = 0; i < n; ++i) {\n        std::size_t bit = n >> 1;\n        for (; j & bit; bit >>= 1) {\n            j ^= bit;\n        }\n        j ^= bit;\n        if (i < j) std::swap(a[i], a[j]);\n    }\n\n    // 2. Bottom-Up Butterfly Stages: len = 2, 4, 8, ..., n\n    for (std::size_t len = 2; len <= n; len <<= 1) {\n        const double ang = 2.0 * std::numbers::pi / static_cast<double>(len) * (invert ? -1.0 : 1.0);\n        const cd wlen(std::cos(ang), std::sin(ang));\n        const std::size_t half = len >> 1;\n\n        for (std::size_t i = 0; i < n; i += len) {\n            cd w(1.0, 0.0);\n            for (std::size_t j = 0; j < half; ++j) {\n                const cd u = a[i + j];\n                const cd v = a[i + j + half] * w;\n                a[i + j]        = u + v;\n                a[i + j + half] = u - v;\n                w *= wlen;\n            }\n        }\n    }\n\n    // 3. Normalize by 1/N for Inverse FFT\n    if (invert) {\n        const double inv_n = 1.0 / static_cast<double>(n);\n        for (cd& x : a) x *= inv_n;\n    }\n}\n\n// Convolves two integer polynomials A and B in O(N log N) time\nstd::vector<std::int64_t> multiply_polynomials_fft(const std::vector<std::int64_t>& A,\n                                                   const std::vector<std::int64_t>& B) {\n    if (A.empty() || B.empty()) return {};\n    const std::size_t result_len = A.size() + B.size() - 1;\n    std::size_t n = 1;\n    while (n < result_len) n <<= 1;\n\n    std::vector<cd> fa(n, cd(0.0, 0.0)), fb(n, cd(0.0, 0.0));\n    for (std::size_t i = 0; i < A.size(); ++i) fa[i] = static_cast<double>(A[i]);\n    for (std::size_t i = 0; i < B.size(); ++i) fb[i] = static_cast<double>(B[i]);\n\n    fft_inplace(fa, false);\n    fft_inplace(fb, false);\n    for (std::size_t i = 0; i < n; ++i) {\n        fa[i] *= fb[i];\n    }\n    fft_inplace(fa, true);\n\n    std::vector<std::int64_t> result(result_len);\n    for (std::size_t i = 0; i < result_len; ++i) {\n        result[i] = static_cast<std::int64_t>(std::llround(fa[i].real()));\n    }\n    return result;\n}\n\nint main() {\n  DESCRIBE(\"Fast Fourier Transform (Cooley-Tukey FFT) & O(N log N) Polynomial Convolution — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes fft_inplace state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes fft_inplace core algorithmic transition (O(n))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies fft_inplace edge cases and space bound (Theta(n^2))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
