    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// C++20: Production Indexed 4-Ary Min-Priority Queue with Hole-Sinking & O(log_4 N) Updates\ntemplate <typename Key, int D = 4>\nclass IndexedDAryMinPQ {\n    std::vector<int> heap; // heap[i] = external handle u at heap slot i\n    std::vector<int> pos;  // pos[u]  = heap slot i of external handle u (-1 if absent)\n    std::vector<Key> keys; // keys[u] = priority key of handle u\n\n    void siftUp(int i) noexcept {      // TODO (Step 1): Implement siftUp(int i)\n      // Maintain the Build Lab: Indexed 4-Ary Min/Max Priority Queue with O(log_d N) decreaseKey invariant (O(1) time, O(log₄ N) space)\n    }\n\n    void siftDown(int i) noexcept {      // TODO (Step 2): Implement siftDown(int i)\n      // Maintain the Build Lab: Indexed 4-Ary Min/Max Priority Queue with O(log_d N) decreaseKey invariant (O(1) time, O(log₄ N) space)\n    }\n\npublic:\n    explicit IndexedDAryMinPQ(int maxHandles) : pos(maxHandles, -1), keys(maxHandles) {\n        heap.reserve(maxHandles);\n    }\n\n    bool empty() const noexcept { return heap.empty(); }\n    int size() const noexcept { return static_cast<int>(heap.size()); }\n    bool contains(int u) const noexcept { return pos[u] != -1; }\n    int peekMinHandle() const noexcept { return heap[0]; }\n    const Key& peekMinKey() const noexcept { return keys[heap[0]]; }\n    const Key& keyOf(int u) const noexcept { return keys[u]; }\n\n    void insert(int u, Key key) {      // TODO (Step 3): Implement insert(int u, Key key)\n      // Maintain the Build Lab: Indexed 4-Ary Min/Max Priority Queue with O(log_d N) decreaseKey invariant (O(1) time, O(log₄ N) space)\n    }\n\n    void decreaseKey(int u, Key newKey) {\n        assert(contains(u) && !(keys[u] < newKey));\n        keys[u] = std::move(newKey);\n        siftUp(pos[u]);\n    }\n\n    void changeKey(int u, Key newKey) {\n        assert(contains(u));\n        bool smaller = (newKey < keys[u]);\n        keys[u] = std::move(newKey);\n        if (smaller) siftUp(pos[u]);\n        else siftDown(pos[u]);\n    }\n\n    void erase(int u) {\n        int i = pos[u];\n        assert(i != -1);\n        int lastHandle = heap.back();\n        heap.pop_back();\n        pos[u] = -1;\n        if (i < static_cast<int>(heap.size())) {\n            heap[i] = lastHandle;\n            pos[lastHandle] = i;\n            siftUp(i);\n            siftDown(i);\n        }\n    }\n\n    std::pair<int, Key> popMin() {\n        int minHandle = heap[0];\n        Key minKey = std::move(keys[minHandle]);\n        erase(minHandle);\n        return {minHandle, std::move(minKey)};\n    }\n};\n\nint main() {\n  DESCRIBE(\"Build Lab: Indexed 4-Ary Min/Max Priority Queue with O(log_d N) decreaseKey — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes IndexedDAryMinPQ state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes IndexedDAryMinPQ core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies IndexedDAryMinPQ edge cases and space bound (O(log₄ N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// C++20: Production Indexed 4-Ary Min-Priority Queue with Hole-Sinking & O(log_4 N) Updates\ntemplate <typename Key, int D = 4>\nclass IndexedDAryMinPQ {\n    std::vector<int> heap; // heap[i] = external handle u at heap slot i\n    std::vector<int> pos;  // pos[u]  = heap slot i of external handle u (-1 if absent)\n    std::vector<Key> keys; // keys[u] = priority key of handle u\n\n    void siftUp(int i) noexcept {\n        int u = heap[i];\n        const Key& k = keys[u];\n        while (i > 0) {\n            int p = (i - 1) / D;\n            int parentHandle = heap[p];\n            if (!(k < keys[parentHandle])) break;\n            heap[i] = parentHandle;\n            pos[parentHandle] = i;\n            i = p;\n        }\n        heap[i] = u;\n        pos[u] = i;\n    }\n\n    void siftDown(int i) noexcept {\n        int u = heap[i];\n        const Key& k = keys[u];\n        const int n = static_cast<int>(heap.size());\n        while (true) {\n            int firstChild = D * i + 1;\n            if (firstChild >= n) break;\n            int lastChild = std::min(n - 1, firstChild + D - 1);\n            int bestChild = firstChild;\n            for (int c = firstChild + 1; c <= lastChild; ++c) {\n                if (keys[heap[c]] < keys[heap[bestChild]]) {\n                    bestChild = c;\n                }\n            }\n            if (!(keys[heap[bestChild]] < k)) break;\n            heap[i] = heap[bestChild];\n            pos[heap[i]] = i;\n            i = bestChild;\n        }\n        heap[i] = u;\n        pos[u] = i;\n    }\n\npublic:\n    explicit IndexedDAryMinPQ(int maxHandles) : pos(maxHandles, -1), keys(maxHandles) {\n        heap.reserve(maxHandles);\n    }\n\n    bool empty() const noexcept { return heap.empty(); }\n    int size() const noexcept { return static_cast<int>(heap.size()); }\n    bool contains(int u) const noexcept { return pos[u] != -1; }\n    int peekMinHandle() const noexcept { return heap[0]; }\n    const Key& peekMinKey() const noexcept { return keys[heap[0]]; }\n    const Key& keyOf(int u) const noexcept { return keys[u]; }\n\n    void insert(int u, Key key) {\n        assert(!contains(u));\n        int idx = static_cast<int>(heap.size());\n        heap.push_back(u);\n        pos[u] = idx;\n        keys[u] = std::move(key);\n        siftUp(idx);\n    }\n\n    void decreaseKey(int u, Key newKey) {\n        assert(contains(u) && !(keys[u] < newKey));\n        keys[u] = std::move(newKey);\n        siftUp(pos[u]);\n    }\n\n    void changeKey(int u, Key newKey) {\n        assert(contains(u));\n        bool smaller = (newKey < keys[u]);\n        keys[u] = std::move(newKey);\n        if (smaller) siftUp(pos[u]);\n        else siftDown(pos[u]);\n    }\n\n    void erase(int u) {\n        int i = pos[u];\n        assert(i != -1);\n        int lastHandle = heap.back();\n        heap.pop_back();\n        pos[u] = -1;\n        if (i < static_cast<int>(heap.size())) {\n            heap[i] = lastHandle;\n            pos[lastHandle] = i;\n            siftUp(i);\n            siftDown(i);\n        }\n    }\n\n    std::pair<int, Key> popMin() {\n        int minHandle = heap[0];\n        Key minKey = std::move(keys[minHandle]);\n        erase(minHandle);\n        return {minHandle, std::move(minKey)};\n    }\n};\n\nint main() {\n  DESCRIBE(\"Build Lab: Indexed 4-Ary Min/Max Priority Queue with O(log_d N) decreaseKey — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes IndexedDAryMinPQ state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes IndexedDAryMinPQ core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies IndexedDAryMinPQ edge cases and space bound (O(log₄ N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
