    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Standard O(1) Idempotent RMQ Sparse Table + O(1) Disjoint Sparse Table (C++20)\nclass SparseTableRMQ {\n    int n, max_k;\n    std::vector<std::vector<int>> st;\npublic:\n    explicit SparseTableRMQ(const std::vector<int>& arr)\n        : n(static_cast<int>(arr.size())),\n          max_k(std::bit_width(static_cast<uint32_t>(n)) - 1),\n          st(max_k + 1, std::vector<int>(n)) {  // TODO (Step 1): Implement SparseTableRMQ(const std::vector<int>& arr)\n        : n(static_cast<int>(arr.size())),\n          max_k(std::bit_width(static_cast<uint32_t>(n)) - 1),\n          st(max_k + 1, std::vector<int>(n))\n  // Maintain the Disjoint & Standard Sparse Tables: O(1) Idempotent Range Minimum Query (RMQ) invariant (O(N) time, O(1) space)\n  return {};}\n\n    int query(int l, int r) const noexcept {      // TODO (Step 2): Implement query(int l, int r)\n      // Maintain the Disjoint & Standard Sparse Tables: O(1) Idempotent Range Minimum Query (RMQ) invariant (O(N) time, O(1) space)\n      return 0;\n    }\n};\n\ntemplate <typename T, typename Op>\nclass DisjointSparseTable {\n    int n, levels;\n    Op op;\n    std::vector<std::vector<T>> table;\npublic:\n    DisjointSparseTable(const std::vector<T>& arr, Op combine = Op{})\n        : n(static_cast<int>(arr.size())),\n          levels(n <= 1 ? 1 : std::bit_width(static_cast<uint32_t>(n - 1))),\n          op(combine),\n          table(levels, std::vector<T>(1 << levels)) {            // TODO (Step 3): Implement levels(n <= 1 ? 1 : std::bit_width(static_cast<uint32_t>(n - 1))),\n          op(combine),\n          table(levels, std::vector<T>(1 << levels))\n            // Maintain the Disjoint & Standard Sparse Tables: O(1) Idempotent Range Minimum Query (RMQ) invariant (O(N) time, O(1) space)\n          }\n\n    T query(int l, int r) const noexcept {\n        if (l == r) return table[levels - 1][l];\n        int msb_diff = std::bit_width(static_cast<uint32_t>(l ^ r)) - 1;\n        int h = levels - 1 - msb_diff;\n        return op(table[h][l], table[h][r]);\n    }\n};\n\nint main() {\n  DESCRIBE(\"Disjoint & Standard Sparse Tables: O(1) Idempotent Range Minimum Query (RMQ) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SparseTableRMQ state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SparseTableRMQ core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SparseTableRMQ edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Standard O(1) Idempotent RMQ Sparse Table + O(1) Disjoint Sparse Table (C++20)\nclass SparseTableRMQ {\n    int n, max_k;\n    std::vector<std::vector<int>> st;\npublic:\n    explicit SparseTableRMQ(const std::vector<int>& arr)\n        : n(static_cast<int>(arr.size())),\n          max_k(std::bit_width(static_cast<uint32_t>(n)) - 1),\n          st(max_k + 1, std::vector<int>(n)) {\n        st[0] = arr;\n        for (int k = 1; k <= max_k; ++k) {\n            int half = 1 << (k - 1);\n            int limit = n - (1 << k);\n            for (int i = 0; i <= limit; ++i) {\n                st[k][i] = std::min(st[k - 1][i], st[k - 1][i + half]);\n            }\n        }\n    }\n\n    int query(int l, int r) const noexcept {\n        int k = std::bit_width(static_cast<uint32_t>(r - l + 1)) - 1;\n        return std::min(st[k][l], st[k][r - (1 << k) + 1]);\n    }\n};\n\ntemplate <typename T, typename Op>\nclass DisjointSparseTable {\n    int n, levels;\n    Op op;\n    std::vector<std::vector<T>> table;\npublic:\n    DisjointSparseTable(const std::vector<T>& arr, Op combine = Op{})\n        : n(static_cast<int>(arr.size())),\n          levels(n <= 1 ? 1 : std::bit_width(static_cast<uint32_t>(n - 1))),\n          op(combine),\n          table(levels, std::vector<T>(1 << levels)) {\n        for (int h = 0; h < levels; ++h) {\n            int block_len = 1 << (levels - h);\n            int half = block_len >> 1;\n            for (int start = 0; start < n; start += block_len) {\n                int mid = std::min(start + half, n);\n                int end = std::min(start + block_len, n);\n                if (mid - 1 < n) {\n                    table[h][mid - 1] = arr[mid - 1];\n                    for (int i = mid - 2; i >= start; --i)\n                        table[h][i] = op(arr[i], table[h][i + 1]);\n                }\n                if (mid < n) {\n                    table[h][mid] = arr[mid];\n                    for (int i = mid + 1; i < end; ++i)\n                        table[h][i] = op(table[h][i - 1], arr[i]);\n                }\n            }\n        }\n    }\n\n    T query(int l, int r) const noexcept {\n        if (l == r) return table[levels - 1][l];\n        int msb_diff = std::bit_width(static_cast<uint32_t>(l ^ r)) - 1;\n        int h = levels - 1 - msb_diff;\n        return op(table[h][l], table[h][r]);\n    }\n};\n\nint main() {\n  DESCRIBE(\"Disjoint & Standard Sparse Tables: O(1) Idempotent Range Minimum Query (RMQ) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SparseTableRMQ state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SparseTableRMQ core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SparseTableRMQ edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
