    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// O(N) Build Fenwick Tree + O(log N) Binary Lifting + Dual Range-Add/Range-Sum BIT (C++20)\nclass FenwickTree {\n    int n;\n    std::vector<int64_t> tree;\npublic:\n    explicit FenwickTree(int size) : n(size), tree(size + 1, 0) {}\n\n    explicit FenwickTree(const std::vector<int64_t>& arr)\n        : n(static_cast<int>(arr.size())), tree(n + 1, 0) {      // TODO (Step 1): Implement FenwickTree(const std::vector<int64_t>& arr)\n        : n(static_cast<int>(arr.size())), tree(n + 1, 0)\n      // Maintain the Fenwick Trees (Binary Indexed Trees): lowbit Geometry, Point Updates & Range Updates invariant (O(N) time, O(log N) space)\n    }\n\n    void add(int idx, int64_t delta) noexcept {\n        for (int i = idx; i <= n; i += i & -i) tree[i] += delta;\n    }\n\n    int64_t prefix_sum(int idx) const noexcept {      // TODO (Step 2): Implement prefix_sum(int idx)\n      // Maintain the Fenwick Trees (Binary Indexed Trees): lowbit Geometry, Point Updates & Range Updates invariant (O(N) time, O(log N) space)\n      return 0;\n    }\n\n    int64_t range_sum(int l, int r) const noexcept {\n        return prefix_sum(r) - prefix_sum(l - 1);\n    }\n\n    // Smallest 1-based index idx such that prefix_sum(idx) >= target_sum\n    int lower_bound(int64_t target_sum) const noexcept {      // TODO (Step 3): Implement lower_bound(int64_t target_sum)\n      // Maintain the Fenwick Trees (Binary Indexed Trees): lowbit Geometry, Point Updates & Range Updates invariant (O(N) time, O(log N) space)\n      return 0;\n    }\n};\n\nclass RangeFenwickTree {\n    int n;\n    FenwickTree b1, b2;\npublic:\n    explicit RangeFenwickTree(int size) : n(size), b1(size), b2(size) {}\n\n    void range_add(int l, int r, int64_t delta) noexcept {\n        b1.add(l, delta);\n        if (r + 1 <= n) b1.add(r + 1, -delta);\n        b2.add(l, delta * l);\n        if (r + 1 <= n) b2.add(r + 1, -delta * (r + 1));\n    }\n\n    int64_t prefix_sum(int x) const noexcept {\n        return (x + 1) * b1.prefix_sum(x) - b2.prefix_sum(x);\n    }\n\n    int64_t range_sum(int l, int r) const noexcept {\n        return prefix_sum(r) - prefix_sum(l - 1);\n    }\n};\n\nint main() {\n  DESCRIBE(\"Fenwick Trees (Binary Indexed Trees): lowbit Geometry, Point Updates & Range Updates — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes FenwickTree state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes FenwickTree core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies FenwickTree edge cases and space bound (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// O(N) Build Fenwick Tree + O(log N) Binary Lifting + Dual Range-Add/Range-Sum BIT (C++20)\nclass FenwickTree {\n    int n;\n    std::vector<int64_t> tree;\npublic:\n    explicit FenwickTree(int size) : n(size), tree(size + 1, 0) {}\n\n    explicit FenwickTree(const std::vector<int64_t>& arr)\n        : n(static_cast<int>(arr.size())), tree(n + 1, 0) {\n        for (int i = 1; i <= n; ++i) {\n            tree[i] += arr[i - 1];\n            int parent = i + (i & -i);\n            if (parent <= n) tree[parent] += tree[i];\n        }\n    }\n\n    void add(int idx, int64_t delta) noexcept {\n        for (int i = idx; i <= n; i += i & -i) tree[i] += delta;\n    }\n\n    int64_t prefix_sum(int idx) const noexcept {\n        int64_t sum = 0;\n        for (int i = idx; i > 0; i -= i & -i) sum += tree[i];\n        return sum;\n    }\n\n    int64_t range_sum(int l, int r) const noexcept {\n        return prefix_sum(r) - prefix_sum(l - 1);\n    }\n\n    // Smallest 1-based index idx such that prefix_sum(idx) >= target_sum\n    int lower_bound(int64_t target_sum) const noexcept {\n        int idx = 0;\n        int bit_mask = 1 << (std::bit_width(static_cast<uint32_t>(n)) - 1);\n        for (; bit_mask > 0; bit_mask >>= 1) {\n            int next = idx + bit_mask;\n            if (next <= n && tree[next] < target_sum) {\n                idx = next;\n                target_sum -= tree[next];\n            }\n        }\n        return idx + 1;\n    }\n};\n\nclass RangeFenwickTree {\n    int n;\n    FenwickTree b1, b2;\npublic:\n    explicit RangeFenwickTree(int size) : n(size), b1(size), b2(size) {}\n\n    void range_add(int l, int r, int64_t delta) noexcept {\n        b1.add(l, delta);\n        if (r + 1 <= n) b1.add(r + 1, -delta);\n        b2.add(l, delta * l);\n        if (r + 1 <= n) b2.add(r + 1, -delta * (r + 1));\n    }\n\n    int64_t prefix_sum(int x) const noexcept {\n        return (x + 1) * b1.prefix_sum(x) - b2.prefix_sum(x);\n    }\n\n    int64_t range_sum(int l, int r) const noexcept {\n        return prefix_sum(r) - prefix_sum(l - 1);\n    }\n};\n\nint main() {\n  DESCRIBE(\"Fenwick Trees (Binary Indexed Trees): lowbit Geometry, Point Updates & Range Updates — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes FenwickTree state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes FenwickTree core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies FenwickTree edge cases and space bound (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
