    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Ji Driver Segment Tree Beats (Range Chmin + Range Sum in O(log N) amortized)\nclass SegmentTreeBeats {\n    int n;\n    static constexpr int64_t NEG_INF = std::numeric_limits<int64_t>::min() / 4;\n    std::vector<int64_t> sum, max1, max2;\n    std::vector<int> cnt_max;\n\n    void pull(int v) noexcept {      // TODO (Step 1): Implement pull(int v)\n      // Maintain the Lazy Propagation & Segment Tree Beats (Ji Driver Segment Tree for Range Chmin/Chmax) invariant (O(1) time, O(1) space)\n    }\n\n    void apply_chmin(int v, int64_t x) noexcept {      // TODO (Step 2): Implement apply_chmin(int v, int64_t x)\n      // Maintain the Lazy Propagation & Segment Tree Beats (Ji Driver Segment Tree for Range Chmin/Chmax) invariant (O(1) time, O(1) space)\n    }\n\n    void push_down(int v) noexcept {      // TODO (Step 3): Implement push_down(int v)\n      // Maintain the Lazy Propagation & Segment Tree Beats (Ji Driver Segment Tree for Range Chmin/Chmax) invariant (O(1) time, O(1) space)\n    }\n\n    void build(int v, int tl, int tr, const std::vector<int64_t>& arr) {\n        if (tl == tr) {\n            sum[v] = max1[v] = arr[tl];\n            max2[v] = NEG_INF;\n            cnt_max[v] = 1;\n            return;\n        }\n        int tm = (tl + tr) >> 1;\n        build(v << 1, tl, tm, arr);\n        build((v << 1) | 1, tm + 1, tr, arr);\n        pull(v);\n    }\npublic:\n    explicit SegmentTreeBeats(const std::vector<int64_t>& arr)\n        : n(static_cast<int>(arr.size())),\n          sum(4 * n), max1(4 * n), max2(4 * n), cnt_max(4 * n) {\n        if (n > 0) build(1, 0, n - 1, arr);\n    }\n\n    void range_chmin(int ql, int qr, int64_t x, int v = 1, int tl = 0, int tr = -1) {\n        if (tr == -1) tr = n - 1;\n        if (ql > tr || qr < tl || x >= max1[v]) return; // Break condition\n        if (ql <= tl && tr <= qr && x > max2[v]) {     // Tag condition\n            apply_chmin(v, x);\n            return;\n        }\n        push_down(v);                                   // Recurse condition\n        int tm = (tl + tr) >> 1;\n        range_chmin(ql, qr, x, v << 1, tl, tm);\n        range_chmin(ql, qr, x, (v << 1) | 1, tm + 1, tr);\n        pull(v);\n    }\n\n    int64_t range_sum(int ql, int qr, int v = 1, int tl = 0, int tr = -1) {\n        if (tr == -1) tr = n - 1;\n        if (ql > tr || qr < tl) return 0;\n        if (ql <= tl && tr <= qr) return sum[v];\n        push_down(v);\n        int tm = (tl + tr) >> 1;\n        return range_sum(ql, qr, v << 1, tl, tm) +\n               range_sum(ql, qr, (v << 1) | 1, tm + 1, tr);\n    }\n};\n\nint main() {\n  DESCRIBE(\"Lazy Propagation & Segment Tree Beats (Ji Driver Segment Tree for Range Chmin/Chmax) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SegmentTreeBeats state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SegmentTreeBeats core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SegmentTreeBeats edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Ji Driver Segment Tree Beats (Range Chmin + Range Sum in O(log N) amortized)\nclass SegmentTreeBeats {\n    int n;\n    static constexpr int64_t NEG_INF = std::numeric_limits<int64_t>::min() / 4;\n    std::vector<int64_t> sum, max1, max2;\n    std::vector<int> cnt_max;\n\n    void pull(int v) noexcept {\n        int L = v << 1, R = L | 1;\n        sum[v] = sum[L] + sum[R];\n        if (max1[L] == max1[R]) {\n            max1[v] = max1[L];\n            max2[v] = std::max(max2[L], max2[R]);\n            cnt_max[v] = cnt_max[L] + cnt_max[R];\n        } else if (max1[L] > max1[R]) {\n            max1[v] = max1[L];\n            max2[v] = std::max(max2[L], max1[R]);\n            cnt_max[v] = cnt_max[L];\n        } else {\n            max1[v] = max1[R];\n            max2[v] = std::max(max1[L], max2[R]);\n            cnt_max[v] = cnt_max[R];\n        }\n    }\n\n    void apply_chmin(int v, int64_t x) noexcept {\n        if (x >= max1[v]) return;\n        sum[v] -= (max1[v] - x) * cnt_max[v];\n        max1[v] = x;\n    }\n\n    void push_down(int v) noexcept {\n        apply_chmin(v << 1, max1[v]);\n        apply_chmin((v << 1) | 1, max1[v]);\n    }\n\n    void build(int v, int tl, int tr, const std::vector<int64_t>& arr) {\n        if (tl == tr) {\n            sum[v] = max1[v] = arr[tl];\n            max2[v] = NEG_INF;\n            cnt_max[v] = 1;\n            return;\n        }\n        int tm = (tl + tr) >> 1;\n        build(v << 1, tl, tm, arr);\n        build((v << 1) | 1, tm + 1, tr, arr);\n        pull(v);\n    }\npublic:\n    explicit SegmentTreeBeats(const std::vector<int64_t>& arr)\n        : n(static_cast<int>(arr.size())),\n          sum(4 * n), max1(4 * n), max2(4 * n), cnt_max(4 * n) {\n        if (n > 0) build(1, 0, n - 1, arr);\n    }\n\n    void range_chmin(int ql, int qr, int64_t x, int v = 1, int tl = 0, int tr = -1) {\n        if (tr == -1) tr = n - 1;\n        if (ql > tr || qr < tl || x >= max1[v]) return; // Break condition\n        if (ql <= tl && tr <= qr && x > max2[v]) {     // Tag condition\n            apply_chmin(v, x);\n            return;\n        }\n        push_down(v);                                   // Recurse condition\n        int tm = (tl + tr) >> 1;\n        range_chmin(ql, qr, x, v << 1, tl, tm);\n        range_chmin(ql, qr, x, (v << 1) | 1, tm + 1, tr);\n        pull(v);\n    }\n\n    int64_t range_sum(int ql, int qr, int v = 1, int tl = 0, int tr = -1) {\n        if (tr == -1) tr = n - 1;\n        if (ql > tr || qr < tl) return 0;\n        if (ql <= tl && tr <= qr) return sum[v];\n        push_down(v);\n        int tm = (tl + tr) >> 1;\n        return range_sum(ql, qr, v << 1, tl, tm) +\n               range_sum(ql, qr, (v << 1) | 1, tm + 1, tr);\n    }\n};\n\nint main() {\n  DESCRIBE(\"Lazy Propagation & Segment Tree Beats (Ji Driver Segment Tree for Range Chmin/Chmax) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SegmentTreeBeats state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SegmentTreeBeats core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SegmentTreeBeats edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
