    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Binary Lifting LCA + K-th Ancestor + Tree Distance (C++20)\nclass BinaryLiftingLCA {\n    int n, log_n, timer = 0;\n    std::vector<std::vector<int>> up;\n    std::vector<int> depth, tin, tout;\n\n    void dfs(int u, int p, const std::vector<std::vector<int>>& adj) {      // TODO (Step 1): Implement dfs(int u, int p, const std::vector<std::vector<int>>& adj)\n      // Maintain the Lowest Common Ancestor (LCA): Binary Lifting vs Euler Tour + ±1 RMQ Reduction invariant (O(1) time, O(sqrtN) space)\n    }\npublic:\n    BinaryLiftingLCA(int n_, const std::vector<std::vector<int>>& adj, int root = 0)\n        : n(n_),\n          log_n(std::bit_width(static_cast<uint32_t>(n_)) + 1),\n          up(log_n, std::vector<int>(n_)),\n          depth(n_, 0), tin(n_, 0), tout(n_, 0) {\n        dfs(root, root, adj);\n    }\n\n    bool is_ancestor(int u, int v) const noexcept {\n        return tin[u] <= tin[v] && tout[v] <= tout[u];\n    }\n\n    int kth_ancestor(int u, int k) const noexcept {      // TODO (Step 2): Implement kth_ancestor(int u, int k)\n      // Maintain the Lowest Common Ancestor (LCA): Binary Lifting vs Euler Tour + ±1 RMQ Reduction invariant (O(1) time, O(sqrtN) space)\n      return 0;\n    }\n\n    int lca(int u, int v) const noexcept {      // TODO (Step 3): Implement lca(int u, int v)\n      // Maintain the Lowest Common Ancestor (LCA): Binary Lifting vs Euler Tour + ±1 RMQ Reduction invariant (O(1) time, O(sqrtN) space)\n      return 0;\n    }\n\n    int dist(int u, int v) const noexcept {\n        int w = lca(u, v);\n        return depth[u] + depth[v] - 2 * depth[w];\n    }\n};\n\nint main() {\n  DESCRIBE(\"Lowest Common Ancestor (LCA): Binary Lifting vs Euler Tour + ±1 RMQ Reduction — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes BinaryLiftingLCA state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes BinaryLiftingLCA core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies BinaryLiftingLCA edge cases and space bound (O(sqrtN))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Binary Lifting LCA + K-th Ancestor + Tree Distance (C++20)\nclass BinaryLiftingLCA {\n    int n, log_n, timer = 0;\n    std::vector<std::vector<int>> up;\n    std::vector<int> depth, tin, tout;\n\n    void dfs(int u, int p, const std::vector<std::vector<int>>& adj) {\n        tin[u] = ++timer;\n        up[0][u] = p;\n        for (int k = 1; k < log_n; ++k) {\n            up[k][u] = up[k - 1][up[k - 1][u]];\n        }\n        for (int v : adj[u]) {\n            if (v != p) {\n                depth[v] = depth[u] + 1;\n                dfs(v, u, adj);\n            }\n        }\n        tout[u] = ++timer;\n    }\npublic:\n    BinaryLiftingLCA(int n_, const std::vector<std::vector<int>>& adj, int root = 0)\n        : n(n_),\n          log_n(std::bit_width(static_cast<uint32_t>(n_)) + 1),\n          up(log_n, std::vector<int>(n_)),\n          depth(n_, 0), tin(n_, 0), tout(n_, 0) {\n        dfs(root, root, adj);\n    }\n\n    bool is_ancestor(int u, int v) const noexcept {\n        return tin[u] <= tin[v] && tout[v] <= tout[u];\n    }\n\n    int kth_ancestor(int u, int k) const noexcept {\n        if (k > depth[u]) return -1;\n        for (int b = 0; k > 0; ++b, k >>= 1) {\n            if (k & 1) u = up[b][u];\n        }\n        return u;\n    }\n\n    int lca(int u, int v) const noexcept {\n        if (is_ancestor(u, v)) return u;\n        if (is_ancestor(v, u)) return v;\n        for (int k = log_n - 1; k >= 0; --k) {\n            if (!is_ancestor(up[k][u], v)) u = up[k][u];\n        }\n        return up[0][u];\n    }\n\n    int dist(int u, int v) const noexcept {\n        int w = lca(u, v);\n        return depth[u] + depth[v] - 2 * depth[w];\n    }\n};\n\nint main() {\n  DESCRIBE(\"Lowest Common Ancestor (LCA): Binary Lifting vs Euler Tour + ±1 RMQ Reduction — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes BinaryLiftingLCA state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes BinaryLiftingLCA core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies BinaryLiftingLCA edge cases and space bound (O(sqrtN))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
