    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Compressed Radix Tree (Compact Prefix Tree) guaranteeing <= 2N nodes (C++20)\ntemplate <typename V>\nclass RadixTree {\n    struct Node {\n        std::string edge;\n        std::optional<V> value;\n        std::unordered_map<char, std::unique_ptr<Node>> children;\n        explicit Node(std::string_view e = \"\", std::optional<V> v = std::nullopt)\n            : edge(e), value(v) {}\n    };\n    std::unique_ptr<Node> root = std::make_unique<Node>();\n\n    static size_t lcp_len(std::string_view a, std::string_view b) noexcept {      // TODO (Step 1): Implement lcp_len(std::string_view a, std::string_view b)\n      // Maintain the Prefix Tries, Compressed Radix Trees & PATRICIA Trees invariant (O(1) time, O(N · L) space)\n      return 0;\n    }\npublic:\n    void insert(std::string_view key, V val) {  // TODO (Step 2): Implement insert(std::string_view key, V val)\n  // Maintain the Prefix Tries, Compressed Radix Trees & PATRICIA Trees invariant (O(1) time, O(N · L) space)\n  return {};}\n\n    std::optional<V> get(std::string_view key) const {      // TODO (Step 3): Implement get(std::string_view key)\n      // Maintain the Prefix Tries, Compressed Radix Trees & PATRICIA Trees invariant (O(1) time, O(N · L) space)\n      return std::nullopt;\n    }\n};\n\nint main() {\n  DESCRIBE(\"Prefix Tries, Compressed Radix Trees & PATRICIA Trees — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes RadixTree state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes RadixTree core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies RadixTree edge cases and space bound (O(N · L))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Compressed Radix Tree (Compact Prefix Tree) guaranteeing <= 2N nodes (C++20)\ntemplate <typename V>\nclass RadixTree {\n    struct Node {\n        std::string edge;\n        std::optional<V> value;\n        std::unordered_map<char, std::unique_ptr<Node>> children;\n        explicit Node(std::string_view e = \"\", std::optional<V> v = std::nullopt)\n            : edge(e), value(v) {}\n    };\n    std::unique_ptr<Node> root = std::make_unique<Node>();\n\n    static size_t lcp_len(std::string_view a, std::string_view b) noexcept {\n        size_t len = std::min(a.size(), b.size()), i = 0;\n        while (i < len && a[i] == b[i]) ++i;\n        return i;\n    }\npublic:\n    void insert(std::string_view key, V val) {\n        Node* curr = root.get();\n        size_t i = 0;\n        while (i < key.size()) {\n            char ch = key[i];\n            auto it = curr->children.find(ch);\n            if (it == curr->children.end()) {\n                curr->children[ch] = std::make_unique<Node>(key.substr(i), val);\n                return;\n            }\n            Node* child = it->second.get();\n            std::string_view rem = key.substr(i);\n            size_t lcp = lcp_len(rem, child->edge);\n            if (lcp == child->edge.size()) {\n                curr = child;\n                i += lcp;\n            } else {\n                auto split = std::make_unique<Node>(std::string_view(child->edge).substr(0, lcp));\n                child->edge.erase(0, lcp);\n                char old_first = child->edge[0];\n                split->children[old_first] = std::move(it->second);\n                if (lcp == rem.size()) {\n                    split->value = val;\n                } else {\n                    std::string_view new_rem = rem.substr(lcp);\n                    split->children[new_rem[0]] = std::make_unique<Node>(new_rem, val);\n                }\n                curr->children[ch] = std::move(split);\n                return;\n            }\n        }\n        curr->value = val;\n    }\n\n    std::optional<V> get(std::string_view key) const {\n        const Node* curr = root.get();\n        size_t i = 0;\n        while (i < key.size()) {\n            auto it = curr->children.find(key[i]);\n            if (it == curr->children.end()) return std::nullopt;\n            const Node* child = it->second.get();\n            if (key.substr(i).compare(0, child->edge.size(), child->edge) != 0)\n                return std::nullopt;\n            curr = child;\n            i += child->edge.size();\n        }\n        return curr->value;\n    }\n};\n\nint main() {\n  DESCRIBE(\"Prefix Tries, Compressed Radix Trees & PATRICIA Trees — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes RadixTree state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes RadixTree core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies RadixTree edge cases and space bound (O(N · L))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
