    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Kasai's O(N) Algorithm: returns lcp[0..N-2] where lcp[r] = LCP(SA[r], SA[r+1])\nstd::vector<int> build_lcp_kasai(std::string_view s, const std::vector<int>& sa) {  // TODO (Step 1): Initialize state structures and base boundary conditions for build_lcp_kasai\n  // TODO (Step 2): Execute core Kasai's O(N) LCP Array Algorithm & Counting Distinct Substrings via SA + LCP transition / loop invariant\n  // TODO (Step 3): Finalize and return verified result\n  return {};}\n\n// Counts total distinct non-empty substrings of S in O(N) after SA + LCP construction\nint64_t count_distinct_substrings(int64_t n, const std::vector<int>& lcp) {\n    int64_t total_substrings = n * (n + 1) / 2;\n    int64_t duplicate_prefixes = std::accumulate(lcp.begin(), lcp.end(), int64_t{0});\n    return total_substrings - duplicate_prefixes;\n}\n\nint main() {\n  DESCRIBE(\"Kasai's O(N) LCP Array Algorithm & Counting Distinct Substrings via SA + LCP — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes build_lcp_kasai state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes build_lcp_kasai core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies build_lcp_kasai edge cases and space bound (O(N log |Sigma|))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Kasai's O(N) Algorithm: returns lcp[0..N-2] where lcp[r] = LCP(SA[r], SA[r+1])\nstd::vector<int> build_lcp_kasai(std::string_view s, const std::vector<int>& sa) {\n    const int n = static_cast<int>(s.size());\n    if (n <= 1) return {};\n\n    std::vector<int> rank(n, 0);\n    for (int r = 0; r < n; ++r) {\n        rank[sa[r]] = r;\n    }\n\n    std::vector<int> lcp(n - 1, 0);\n    int h = 0;\n    for (int i = 0; i < n; ++i) {\n        if (rank[i] == n - 1) {\n            h = 0;\n            continue;\n        }\n        int j = sa[rank[i] + 1];\n        while (i + h < n && j + h < n && s[i + h] == s[j + h]) {\n            ++h;\n        }\n        lcp[rank[i]] = h;\n        if (h > 0) --h;\n    }\n    return lcp;\n}\n\n// Counts total distinct non-empty substrings of S in O(N) after SA + LCP construction\nint64_t count_distinct_substrings(int64_t n, const std::vector<int>& lcp) {\n    int64_t total_substrings = n * (n + 1) / 2;\n    int64_t duplicate_prefixes = std::accumulate(lcp.begin(), lcp.end(), int64_t{0});\n    return total_substrings - duplicate_prefixes;\n}\n\nint main() {\n  DESCRIBE(\"Kasai's O(N) LCP Array Algorithm & Counting Distinct Substrings via SA + LCP — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes build_lcp_kasai state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes build_lcp_kasai core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies build_lcp_kasai edge cases and space bound (O(N log |Sigma|))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
