    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass SuffixAutomaton {\npublic:\n    struct State {\n        std::array<int, 26> next;\n        int len = 0;\n        int link = -1;\n        State() { next.fill(-1); }\n    };\n\n    explicit SuffixAutomaton(std::string_view s) {      // TODO (Step 1): Implement SuffixAutomaton(std::string_view s)\n      // Maintain the Suffix Automaton (SAM / DAWG): endpos Equivalence Classes & State Transitions invariant (O(N) time, O(N) space)\n    }\n\n    void extend(int c) {      // TODO (Step 2): Implement extend(int c)\n      // Maintain the Suffix Automaton (SAM / DAWG): endpos Equivalence Classes & State Transitions invariant (O(N) time, O(N) space)\n    }\n\n    int64_t count_distinct_substrings() const {      // TODO (Step 3): Implement count_distinct_substrings()\n      // Maintain the Suffix Automaton (SAM / DAWG): endpos Equivalence Classes & State Transitions invariant (O(N) time, O(N) space)\n      return 0;\n    }\n\n    // Returns length of Longest Common Substring with T in O(|T|) time\n    int longest_common_substring(std::string_view t) const {\n        int u = 0, cur_len = 0, best = 0;\n        for (char ch : t) {\n            int c = ch - 'a';\n            while (u != 0 && st_[u].next[c] == -1) {\n                u = st_[u].link;\n                cur_len = st_[u].len;\n            }\n            if (st_[u].next[c] != -1) {\n                u = st_[u].next[c];\n                ++cur_len;\n            }\n            best = std::max(best, cur_len);\n        }\n        return best;\n    }\n\nprivate:\n    std::vector<State> st_;\n    int last_ = 0;\n};\n\nint main() {\n  DESCRIBE(\"Suffix Automaton (SAM / DAWG): endpos Equivalence Classes & State Transitions — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SuffixAutomaton state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SuffixAutomaton core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SuffixAutomaton edge cases and space bound (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass SuffixAutomaton {\npublic:\n    struct State {\n        std::array<int, 26> next;\n        int len = 0;\n        int link = -1;\n        State() { next.fill(-1); }\n    };\n\n    explicit SuffixAutomaton(std::string_view s) {\n        st_.reserve(2 * s.size() + 1);\n        st_.emplace_back(); // State 0 = root\n        for (char ch : s) extend(ch - 'a');\n    }\n\n    void extend(int c) {\n        int cur = static_cast<int>(st_.size());\n        st_.emplace_back();\n        st_[cur].len = st_[last_].len + 1;\n\n        int p = last_;\n        while (p != -1 && st_[p].next[c] == -1) {\n            st_[p].next[c] = cur;\n            p = st_[p].link;\n        }\n        if (p == -1) {\n            st_[cur].link = 0;\n        } else {\n            int q = st_[p].next[c];\n            if (st_[p].len + 1 == st_[q].len) {\n                st_[cur].link = q;\n            } else {\n                int clone = static_cast<int>(st_.size());\n                st_.push_back(st_[q]); // Copies next[] and link\n                st_[clone].len = st_[p].len + 1;\n                while (p != -1 && st_[p].next[c] == q) {\n                    st_[p].next[c] = clone;\n                    p = st_[p].link;\n                }\n                st_[q].link = st_[cur].link = clone;\n            }\n        }\n        last_ = cur;\n    }\n\n    int64_t count_distinct_substrings() const {\n        int64_t total = 0;\n        for (size_t u = 1; u < st_.size(); ++u) {\n            total += st_[u].len - st_[st_[u].link].len;\n        }\n        return total;\n    }\n\n    // Returns length of Longest Common Substring with T in O(|T|) time\n    int longest_common_substring(std::string_view t) const {\n        int u = 0, cur_len = 0, best = 0;\n        for (char ch : t) {\n            int c = ch - 'a';\n            while (u != 0 && st_[u].next[c] == -1) {\n                u = st_[u].link;\n                cur_len = st_[u].len;\n            }\n            if (st_[u].next[c] != -1) {\n                u = st_[u].next[c];\n                ++cur_len;\n            }\n            best = std::max(best, cur_len);\n        }\n        return best;\n    }\n\nprivate:\n    std::vector<State> st_;\n    int last_ = 0;\n};\n\nint main() {\n  DESCRIBE(\"Suffix Automaton (SAM / DAWG): endpos Equivalence Classes & State Transitions — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes SuffixAutomaton state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes SuffixAutomaton core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies SuffixAutomaton edge cases and space bound (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
