    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass TwoSatSolver {\npublic:\n    explicit TwoSatSolver(int numVars)\n        : n(numVars), adj(2 * numVars), tin(2 * numVars, 0),\n          low(2 * numVars, 0), comp(2 * numVars, -1),\n          onStack(2 * numVars, 0), assignment(numVars, false) {\n        st.reserve(2 * numVars);\n    }\n\n    static int lit(int var, bool isTrue) noexcept {\n        return 2 * var + (isTrue ? 0 : 1);\n    }\n\n    // Adds (u OR v) where u, v are literal indices in [0, 2n-1]\n    void addClause(int u, int v) {      // TODO (Step 1): Implement addClause(int u, int v)\n      // Maintain the Build Lab: Tarjan's SCC Condensation DAG & Linear-Time 2-SAT Constraint Solver invariant (O(1) time, O(K^2) space)\n    }\n\n    void addXor(int u, int v) {      // TODO (Step 2): Implement addXor(int u, int v)\n      // Maintain the Build Lab: Tarjan's SCC Condensation DAG & Linear-Time 2-SAT Constraint Solver invariant (O(1) time, O(K^2) space)\n    }\n\n    void addEq(int u, int v) {      // TODO (Step 3): Implement addEq(int u, int v)\n      // Maintain the Build Lab: Tarjan's SCC Condensation DAG & Linear-Time 2-SAT Constraint Solver invariant (O(1) time, O(K^2) space)\n    }\n\n    bool solve() {\n        for (int i = 0; i < 2 * n; ++i) {\n            if (tin[i] == 0) dfs(i);\n        }\n        for (int i = 0; i < n; ++i) {\n            if (comp[2 * i] == comp[2 * i + 1]) return false;\n            // In Tarjan's SCC, smaller component ID means closer to a sink in the DAG\n            assignment[i] = (comp[2 * i] < comp[2 * i + 1]);\n        }\n        return true;\n    }\n\n    const std::vector<bool>& values() const noexcept { return assignment; }\n\nprivate:\n    int n, timer = 0, sccCount = 0;\n    std::vector<std::vector<int>> adj;\n    std::vector<int> tin, low, comp, st;\n    std::vector<uint8_t> onStack;\n    std::vector<bool> assignment;\n\n    void dfs(int u) {\n        tin[u] = low[u] = ++timer;\n        st.push_back(u);\n        onStack[u] = 1;\n        for (int v : adj[u]) {\n            if (tin[v] == 0) {\n                dfs(v);\n                low[u] = std::min(low[u], low[v]);\n            } else if (onStack[v]) {\n                low[u] = std::min(low[u], tin[v]);\n            }\n        }\n        if (low[u] == tin[u]) {\n            while (true) {\n                int w = st.back();\n                st.pop_back();\n                onStack[w] = 0;\n                comp[w] = sccCount;\n                if (w == u) break;\n            }\n            ++sccCount;\n        }\n    }\n};\n\nint main() {\n  DESCRIBE(\"Build Lab: Tarjan's SCC Condensation DAG & Linear-Time 2-SAT Constraint Solver — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes TwoSatSolver state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes TwoSatSolver core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies TwoSatSolver edge cases and space bound (O(K^2))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass TwoSatSolver {\npublic:\n    explicit TwoSatSolver(int numVars)\n        : n(numVars), adj(2 * numVars), tin(2 * numVars, 0),\n          low(2 * numVars, 0), comp(2 * numVars, -1),\n          onStack(2 * numVars, 0), assignment(numVars, false) {\n        st.reserve(2 * numVars);\n    }\n\n    static int lit(int var, bool isTrue) noexcept {\n        return 2 * var + (isTrue ? 0 : 1);\n    }\n\n    // Adds (u OR v) where u, v are literal indices in [0, 2n-1]\n    void addClause(int u, int v) {\n        adj[u ^ 1].push_back(v);\n        adj[v ^ 1].push_back(u);\n    }\n\n    void addXor(int u, int v) {\n        addClause(u, v);\n        addClause(u ^ 1, v ^ 1);\n    }\n\n    void addEq(int u, int v) {\n        addClause(u ^ 1, v);\n        addClause(u, v ^ 1);\n    }\n\n    bool solve() {\n        for (int i = 0; i < 2 * n; ++i) {\n            if (tin[i] == 0) dfs(i);\n        }\n        for (int i = 0; i < n; ++i) {\n            if (comp[2 * i] == comp[2 * i + 1]) return false;\n            // In Tarjan's SCC, smaller component ID means closer to a sink in the DAG\n            assignment[i] = (comp[2 * i] < comp[2 * i + 1]);\n        }\n        return true;\n    }\n\n    const std::vector<bool>& values() const noexcept { return assignment; }\n\nprivate:\n    int n, timer = 0, sccCount = 0;\n    std::vector<std::vector<int>> adj;\n    std::vector<int> tin, low, comp, st;\n    std::vector<uint8_t> onStack;\n    std::vector<bool> assignment;\n\n    void dfs(int u) {\n        tin[u] = low[u] = ++timer;\n        st.push_back(u);\n        onStack[u] = 1;\n        for (int v : adj[u]) {\n            if (tin[v] == 0) {\n                dfs(v);\n                low[u] = std::min(low[u], low[v]);\n            } else if (onStack[v]) {\n                low[u] = std::min(low[u], tin[v]);\n            }\n        }\n        if (low[u] == tin[u]) {\n            while (true) {\n                int w = st.back();\n                st.pop_back();\n                onStack[w] = 0;\n                comp[w] = sccCount;\n                if (w == u) break;\n            }\n            ++sccCount;\n        }\n    }\n};\n\nint main() {\n  DESCRIBE(\"Build Lab: Tarjan's SCC Condensation DAG & Linear-Time 2-SAT Constraint Solver — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes TwoSatSolver state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes TwoSatSolver core algorithmic transition (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies TwoSatSolver edge cases and space bound (O(K^2))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
