    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass DisjointSetUnion {\npublic:\n    explicit DisjointSetUnion(int n) : parentOrNegSize(n, -1), numComponents(n) {}\n\n    int find(int x) noexcept {\n        int root = x;\n        while (parentOrNegSize[root] >= 0) {\n            root = parentOrNegSize[root];\n        }\n        while (x != root) {\n            int next = parentOrNegSize[x];\n            parentOrNegSize[x] = root;\n            x = next;\n        }\n        return root;\n    }\n\n    bool unite(int a, int b) noexcept {      // TODO (Step 1): Initialize state structures and base boundary conditions for unite\n      // TODO (Step 2): Execute core Disjoint Set Union (Union-Find): Union by Rank + Path Compression & O(α(N)) Proof Intuition transition / loop invariant\n      // TODO (Step 3): Finalize and return verified result\n      return false;\n    }\n\n    bool connected(int a, int b) noexcept { return find(a) == find(b); }\n    int componentSize(int x) noexcept { return -parentOrNegSize[find(x)]; }\n    int components() const noexcept { return numComponents; }\n\nprivate:\n    std::vector<int> parentOrNegSize;\n    int numComponents;\n};\n\nint main() {\n  DESCRIBE(\"Disjoint Set Union (Union-Find): Union by Rank + Path Compression & O(α(N)) Proof Intuition — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes DisjointSetUnion state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes DisjointSetUnion core algorithmic transition (Theta(N + M α(M, N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies DisjointSetUnion edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass DisjointSetUnion {\npublic:\n    explicit DisjointSetUnion(int n) : parentOrNegSize(n, -1), numComponents(n) {}\n\n    int find(int x) noexcept {\n        int root = x;\n        while (parentOrNegSize[root] >= 0) {\n            root = parentOrNegSize[root];\n        }\n        while (x != root) {\n            int next = parentOrNegSize[x];\n            parentOrNegSize[x] = root;\n            x = next;\n        }\n        return root;\n    }\n\n    bool unite(int a, int b) noexcept {\n        a = find(a);\n        b = find(b);\n        if (a == b) return false;\n        // Remember: more negative means LARGER component size!\n        if (parentOrNegSize[a] > parentOrNegSize[b]) {\n            std::swap(a, b);\n        }\n        parentOrNegSize[a] += parentOrNegSize[b];\n        parentOrNegSize[b] = a;\n        --numComponents;\n        return true;\n    }\n\n    bool connected(int a, int b) noexcept { return find(a) == find(b); }\n    int componentSize(int x) noexcept { return -parentOrNegSize[find(x)]; }\n    int components() const noexcept { return numComponents; }\n\nprivate:\n    std::vector<int> parentOrNegSize;\n    int numComponents;\n};\n\nint main() {\n  DESCRIBE(\"Disjoint Set Union (Union-Find): Union by Rank + Path Compression & O(α(N)) Proof Intuition — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes DisjointSetUnion state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes DisjointSetUnion core algorithmic transition (Theta(N + M α(M, N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies DisjointSetUnion edge cases and space bound (O(1))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
