    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass RollbackDSU {\npublic:\n    explicit RollbackDSU(int n) : p(n, -1), comps(n) {}\n\n    int find(int x) const noexcept {      // TODO (Step 1): Implement find(int x)\n      // Maintain the Weighted DSU (Potentials/Parity) & Rollback DSU for Dynamic Connectivity Over Time invariant (O(log N) time, O(log N) space)\n      return 0;\n    }\n\n    bool unite(int a, int b) {      // TODO (Step 2): Implement unite(int a, int b)\n      // Maintain the Weighted DSU (Potentials/Parity) & Rollback DSU for Dynamic Connectivity Over Time invariant (O(log N) time, O(log N) space)\n      return false;\n    }\n\n    size_t snapshot() const noexcept { return history.size(); }\n\n    void rollback(size_t targetSize) noexcept {      // TODO (Step 3): Implement rollback(size_t targetSize)\n      // Maintain the Weighted DSU (Potentials/Parity) & Rollback DSU for Dynamic Connectivity Over Time invariant (O(log N) time, O(log N) space)\n    }\n\n    int components() const noexcept { return comps; }\n\nprivate:\n    std::vector<int> p;\n    std::vector<std::pair<int, int>> history;\n    int comps;\n};\n\nclass WeightedDSU {\npublic:\n    explicit WeightedDSU(int n) : parent(n, -1), diff(n, 0) {}\n\n    // Returns (root, phi(x) - phi(root))\n    std::pair<int, long long> find(int x) {\n        if (parent[x] < 0) return {x, 0};\n        auto [r, dParent] = find(parent[x]);\n        parent[x] = r;\n        diff[x] += dParent;\n        return {r, diff[x]};\n    }\n\n    // Enforces phi(u) - phi(v) == w. Returns false if inconsistent with existing component!\n    bool unite(int u, int v, long long w) {\n        auto [ru, du] = find(u);\n        auto [rv, dv] = find(v);\n        if (ru == rv) return (du - dv) == w;\n        if (parent[ru] > parent[rv]) {\n            parent[rv] += parent[ru];\n            parent[ru] = rv;\n            diff[ru] = w + dv - du;\n        } else {\n            parent[ru] += parent[rv];\n            parent[rv] = ru;\n            diff[rv] = du - dv - w;\n        }\n        return true;\n    }\n\nprivate:\n    std::vector<int> parent;\n    std::vector<long long> diff;\n};\n\nint main() {\n  DESCRIBE(\"Weighted DSU (Potentials/Parity) & Rollback DSU for Dynamic Connectivity Over Time — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes RollbackDSU state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes RollbackDSU core algorithmic transition (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies RollbackDSU edge cases and space bound (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass RollbackDSU {\npublic:\n    explicit RollbackDSU(int n) : p(n, -1), comps(n) {}\n\n    int find(int x) const noexcept {\n        while (p[x] >= 0) x = p[x];\n        return x;\n    }\n\n    bool unite(int a, int b) {\n        a = find(a);\n        b = find(b);\n        if (a == b) return false;\n        if (p[a] > p[b]) std::swap(a, b); // p[a] is more negative (larger size)\n        history.emplace_back(b, p[b]);\n        p[a] += p[b];\n        p[b] = a;\n        --comps;\n        return true;\n    }\n\n    size_t snapshot() const noexcept { return history.size(); }\n\n    void rollback(size_t targetSize) noexcept {\n        while (history.size() > targetSize) {\n            auto [b, oldNegSizeB] = history.back();\n            history.pop_back();\n            int a = p[b];\n            p[a] -= oldNegSizeB;\n            p[b] = oldNegSizeB;\n            ++comps;\n        }\n    }\n\n    int components() const noexcept { return comps; }\n\nprivate:\n    std::vector<int> p;\n    std::vector<std::pair<int, int>> history;\n    int comps;\n};\n\nclass WeightedDSU {\npublic:\n    explicit WeightedDSU(int n) : parent(n, -1), diff(n, 0) {}\n\n    // Returns (root, phi(x) - phi(root))\n    std::pair<int, long long> find(int x) {\n        if (parent[x] < 0) return {x, 0};\n        auto [r, dParent] = find(parent[x]);\n        parent[x] = r;\n        diff[x] += dParent;\n        return {r, diff[x]};\n    }\n\n    // Enforces phi(u) - phi(v) == w. Returns false if inconsistent with existing component!\n    bool unite(int u, int v, long long w) {\n        auto [ru, du] = find(u);\n        auto [rv, dv] = find(v);\n        if (ru == rv) return (du - dv) == w;\n        if (parent[ru] > parent[rv]) {\n            parent[rv] += parent[ru];\n            parent[ru] = rv;\n            diff[ru] = w + dv - du;\n        } else {\n            parent[ru] += parent[rv];\n            parent[rv] = ru;\n            diff[rv] = du - dv - w;\n        }\n        return true;\n    }\n\nprivate:\n    std::vector<int> parent;\n    std::vector<long long> diff;\n};\n\nint main() {\n  DESCRIBE(\"Weighted DSU (Potentials/Parity) & Rollback DSU for Dynamic Connectivity Over Time — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes RollbackDSU state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes RollbackDSU core algorithmic transition (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies RollbackDSU edge cases and space bound (O(log N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
