    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass PushRelabel {\npublic:\n    struct Arc {\n        int to;\n        long long cap;\n    };\n\n    explicit PushRelabel(int n) : n(n), adj(n), excess(n, 0), h(n, 0), count(2 * n + 1, 0), buckets(2 * n + 1) {}\n\n    void addEdge(int u, int v, long long cap) {      // TODO (Step 1): Implement addEdge(int u, int v, long long cap)\n      // Maintain the Push-Relabel (Goldberg-Tarjan): Preflows, Height Functions & Highest-Label Selection invariant (O(V^2) time, O(V E) space)\n    }\n\n    long long maxFlow(int s, int t) {      // TODO (Step 2): Implement maxFlow(int s, int t)\n      // Maintain the Push-Relabel (Goldberg-Tarjan): Preflows, Height Functions & Highest-Label Selection invariant (O(V^2) time, O(V E) space)\n      return 0;\n    }\n\nprivate:\n    int n, maxHeight = 0;\n    std::vector<Arc> arcs;\n    std::vector<std::vector<int>> adj;\n    std::vector<long long> excess;\n    std::vector<int> h, count;\n    std::vector<std::vector<int>> buckets;\n\n    void push(int u, int id, long long d) {      // TODO (Step 3): Implement push(int u, int id, long long d)\n      // Maintain the Push-Relabel (Goldberg-Tarjan): Preflows, Height Functions & Highest-Label Selection invariant (O(V^2) time, O(V E) space)\n    }\n\n    void discharge(int u, int s, int t) {\n        while (excess[u] > 0) {\n            int minNeighborH = 2 * n;\n            for (int id : adj[u]) {\n                if (arcs[id].cap == 0) continue;\n                int v = arcs[id].to;\n                if (h[u] == h[v] + 1) {\n                    push(u, id, std::min(excess[u], arcs[id].cap));\n                    if (excess[u] == 0) return;\n                } else {\n                    minNeighborH = std::min(minNeighborH, h[v]);\n                }\n            }\n            // Relabel with Gap Heuristic\n            int oldH = h[u];\n            --count[oldH];\n            if (count[oldH] == 0 && oldH < n) {\n                for (int i = 0; i < n; ++i) {\n                    if (i != s && i != t && h[i] > oldH && h[i] <= n) {\n                        --count[h[i]];\n                        h[i] = n + 1;\n                    }\n                }\n            }\n            h[u] = minNeighborH + 1;\n            ++count[h[u]];\n            if (h[u] >= n) return; // Excess will drain back to s in phase 2 or can be ignored for maxFlow value\n        }\n    }\n};\n\nint main() {\n  DESCRIBE(\"Push-Relabel (Goldberg-Tarjan): Preflows, Height Functions & Highest-Label Selection — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes PushRelabel state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes PushRelabel core algorithmic transition (O(V^2))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies PushRelabel edge cases and space bound (O(V E))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass PushRelabel {\npublic:\n    struct Arc {\n        int to;\n        long long cap;\n    };\n\n    explicit PushRelabel(int n) : n(n), adj(n), excess(n, 0), h(n, 0), count(2 * n + 1, 0), buckets(2 * n + 1) {}\n\n    void addEdge(int u, int v, long long cap) {\n        if (u == v) return;\n        adj[u].push_back(static_cast<int>(arcs.size()));\n        arcs.push_back({v, cap});\n        adj[v].push_back(static_cast<int>(arcs.size()));\n        arcs.push_back({u, 0});\n    }\n\n    long long maxFlow(int s, int t) {\n        h[s] = n;\n        excess[t] = 1; // Prevent t from being added to active buckets\n        count[0] = n - 1;\n\n        for (int id : adj[s]) {\n            push(s, id, arcs[id].cap);\n        }\n\n        while (maxHeight >= 0) {\n            if (buckets[maxHeight].empty()) {\n                --maxHeight;\n                continue;\n            }\n            int u = buckets[maxHeight].back();\n            buckets[maxHeight].pop_back();\n            discharge(u, s, t);\n        }\n        return excess[t] - 1;\n    }\n\nprivate:\n    int n, maxHeight = 0;\n    std::vector<Arc> arcs;\n    std::vector<std::vector<int>> adj;\n    std::vector<long long> excess;\n    std::vector<int> h, count;\n    std::vector<std::vector<int>> buckets;\n\n    void push(int u, int id, long long d) {\n        if (d == 0) return;\n        int v = arcs[id].to;\n        if (excess[v] == 0 && h[v] < n) {\n            buckets[h[v]].push_back(v);\n            maxHeight = std::max(maxHeight, h[v]);\n        }\n        arcs[id].cap -= d;\n        arcs[id ^ 1].cap += d;\n        excess[u] -= d;\n        excess[v] += d;\n    }\n\n    void discharge(int u, int s, int t) {\n        while (excess[u] > 0) {\n            int minNeighborH = 2 * n;\n            for (int id : adj[u]) {\n                if (arcs[id].cap == 0) continue;\n                int v = arcs[id].to;\n                if (h[u] == h[v] + 1) {\n                    push(u, id, std::min(excess[u], arcs[id].cap));\n                    if (excess[u] == 0) return;\n                } else {\n                    minNeighborH = std::min(minNeighborH, h[v]);\n                }\n            }\n            // Relabel with Gap Heuristic\n            int oldH = h[u];\n            --count[oldH];\n            if (count[oldH] == 0 && oldH < n) {\n                for (int i = 0; i < n; ++i) {\n                    if (i != s && i != t && h[i] > oldH && h[i] <= n) {\n                        --count[h[i]];\n                        h[i] = n + 1;\n                    }\n                }\n            }\n            h[u] = minNeighborH + 1;\n            ++count[h[u]];\n            if (h[u] >= n) return; // Excess will drain back to s in phase 2 or can be ignored for maxFlow value\n        }\n    }\n};\n\nint main() {\n  DESCRIBE(\"Push-Relabel (Goldberg-Tarjan): Preflows, Height Functions & Highest-Label Selection — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes PushRelabel state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes PushRelabel core algorithmic transition (O(V^2))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies PushRelabel edge cases and space bound (O(V E))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
