    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass HopcroftKarp {\npublic:\n    HopcroftKarp(int nLeft, int nRight)\n        : nL(nLeft), nR(nRight), adj(nLeft), matchL(nLeft, -1), matchR(nRight, -1), dist(nLeft) {}\n\n    void addEdge(int u, int v) { adj[u].push_back(v); }\n\n    int maxMatching() {      // TODO (Step 1): Implement maxMatching()\n      // Maintain the Maximum Bipartite Matching: König's Theorem, Hall's Marriage Theorem & Hopcroft-Karp O(E√V) invariant (O(E sqrtV) time, O(E sqrtV) space)\n      return 0;\n    }\n\n    // Returns {chosenLeftNodes, chosenRightNodes} forming a Minimum Vertex Cover\n    std::pair<std::vector<int>, std::vector<int>> minVertexCover() {      // TODO (Step 2): Implement minVertexCover()\n      // Maintain the Maximum Bipartite Matching: König's Theorem, Hall's Marriage Theorem & Hopcroft-Karp O(E√V) invariant (O(E sqrtV) time, O(E sqrtV) space)\n      return {};\n    }\n\nprivate:\n    static constexpr int INF = 1e9;\n    int nL, nR;\n    std::vector<std::vector<int>> adj;\n    std::vector<int> matchL, matchR, dist;\n\n    bool bfs() {      // TODO (Step 3): Implement bfs()\n      // Maintain the Maximum Bipartite Matching: König's Theorem, Hall's Marriage Theorem & Hopcroft-Karp O(E√V) invariant (O(E sqrtV) time, O(E sqrtV) space)\n      return false;\n    }\n\n    bool dfs(int u) {\n        for (int v : adj[u]) {\n            int nextU = matchR[v];\n            if (nextU == -1 || (dist[nextU] == dist[u] + 1 && dfs(nextU))) {\n                matchL[u] = v;\n                matchR[v] = u;\n                return true;\n            }\n        }\n        dist[u] = INF; // Dead-end pruning: never revisit u in this phase\n        return false;\n    }\n};\n\nint main() {\n  DESCRIBE(\"Maximum Bipartite Matching: König's Theorem, Hall's Marriage Theorem & Hopcroft-Karp O(E√V) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes HopcroftKarp state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes HopcroftKarp core algorithmic transition (O(E sqrtV))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies HopcroftKarp edge cases and space bound (O(E sqrtV))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\nclass HopcroftKarp {\npublic:\n    HopcroftKarp(int nLeft, int nRight)\n        : nL(nLeft), nR(nRight), adj(nLeft), matchL(nLeft, -1), matchR(nRight, -1), dist(nLeft) {}\n\n    void addEdge(int u, int v) { adj[u].push_back(v); }\n\n    int maxMatching() {\n        int matching = 0;\n        while (bfs()) {\n            for (int u = 0; u < nL; ++u) {\n                if (matchL[u] == -1 && dfs(u)) {\n                    ++matching;\n                }\n            }\n        }\n        return matching;\n    }\n\n    // Returns {chosenLeftNodes, chosenRightNodes} forming a Minimum Vertex Cover\n    std::pair<std::vector<int>, std::vector<int>> minVertexCover() {\n        std::vector<uint8_t> visL(nL, 0), visR(nR, 0);\n        std::queue<int> q;\n        for (int u = 0; u < nL; ++u) {\n            if (matchL[u] == -1) {\n                visL[u] = 1;\n                q.push(u);\n            }\n        }\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int v : adj[u]) {\n                if (v != matchL[u] && !visR[v]) {\n                    visR[v] = 1;\n                    int nextU = matchR[v];\n                    if (nextU != -1 && !visL[nextU]) {\n                        visL[nextU] = 1;\n                        q.push(nextU);\n                    }\n                }\n            }\n        }\n        std::vector<int> coverL, coverR;\n        for (int u = 0; u < nL; ++u) if (!visL[u]) coverL.push_back(u); // L  Z\n        for (int v = 0; v < nR; ++v) if (visR[v]) coverR.push_back(v);  // R n Z\n        return {coverL, coverR};\n    }\n\nprivate:\n    static constexpr int INF = 1e9;\n    int nL, nR;\n    std::vector<std::vector<int>> adj;\n    std::vector<int> matchL, matchR, dist;\n\n    bool bfs() {\n        std::queue<int> q;\n        for (int u = 0; u < nL; ++u) {\n            if (matchL[u] == -1) {\n                dist[u] = 0;\n                q.push(u);\n            } else {\n                dist[u] = INF;\n            }\n        }\n        bool foundAugmenting = false;\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int v : adj[u]) {\n                int nextU = matchR[v];\n                if (nextU == -1) {\n                    foundAugmenting = true;\n                } else if (dist[nextU] == INF) {\n                    dist[nextU] = dist[u] + 1;\n                    q.push(nextU);\n                }\n            }\n        }\n        return foundAugmenting;\n    }\n\n    bool dfs(int u) {\n        for (int v : adj[u]) {\n            int nextU = matchR[v];\n            if (nextU == -1 || (dist[nextU] == dist[u] + 1 && dfs(nextU))) {\n                matchL[u] = v;\n                matchR[v] = u;\n                return true;\n            }\n        }\n        dist[u] = INF; // Dead-end pruning: never revisit u in this phase\n        return false;\n    }\n};\n\nint main() {\n  DESCRIBE(\"Maximum Bipartite Matching: König's Theorem, Hall's Marriage Theorem & Hopcroft-Karp O(E√V) — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes HopcroftKarp state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes HopcroftKarp core algorithmic transition (O(E sqrtV))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies HopcroftKarp edge cases and space bound (O(E sqrtV))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
