    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// 1. Matrix Chain Multiplication with Transpose-Cache Optimization (p has size n + 1)\nlong long matrix_chain_multiplication(const std::vector<long long>& p) {  // TODO (Step 1): Initialize state structures and base boundary conditions for matrix_chain_multiplication\n  // TODO (Step 2): Execute core Interval DP: Matrix Chain Multiplication, Optimal BST & Polygon Triangulation transition / loop invariant\n  // TODO (Step 3): Finalize and return verified result\n  return 0;}\n\n// 2. Burst Balloons: Guess the LAST balloon popped inside open interval (i, j)\nlong long max_coins_burst_balloons(const std::vector<int>& nums) {\n    // Pad with virtual boundary balloons of value 1 at both ends\n    std::vector<long long> a;\n    a.reserve(nums.size() + 2);\n    a.push_back(1);\n    for (int x : nums) if (x > 0) a.push_back(x);\n    a.push_back(1);\n\n    const int m = static_cast<int>(a.size());\n    std::vector<std::vector<long long>> dp(m, std::vector<long long>(m, 0));\n\n    // len is the distance j - i between open interval boundaries (minimum 2)\n    for (int len = 2; len < m; ++len) {\n        for (int i = 0; i + len < m; ++i) {\n            const int j = i + len;\n            const long long boundary_prod = a[i] * a[j];\n            long long best = 0;\n            for (int k = i + 1; k < j; ++k) {\n                best = std::max(best, dp[i][k] + dp[k][j] + boundary_prod * a[k]);\n            }\n            dp[i][j] = best;\n        }\n    }\n    return dp[0][m - 1];\n}\n\nint main() {\n  DESCRIBE(\"Interval DP: Matrix Chain Multiplication, Optimal BST & Polygon Triangulation — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes matrix_chain_multiplication state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes matrix_chain_multiplication core algorithmic transition (O(N^3))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies matrix_chain_multiplication edge cases and space bound (O(N^2))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// 1. Matrix Chain Multiplication with Transpose-Cache Optimization (p has size n + 1)\nlong long matrix_chain_multiplication(const std::vector<long long>& p) {\n    const int n = static_cast<int>(p.size()) - 1;\n    if (n <= 1) return 0;\n    constexpr long long INF = 1LL << 60;\n\n    // dp[i][j] = min scalar multiplications for A_i .. A_j\n    // dpT[j][i] = transposed copy of dp[i][j] so inner k-loop has stride-1 on both arrays!\n    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));\n    std::vector<std::vector<long long>> dpT(n, std::vector<long long>(n, 0));\n\n    for (int len = 2; len <= n; ++len) {\n        for (int i = 0; i + len - 1 < n; ++i) {\n            const int j = i + len - 1;\n            const long long outer_p = p[i] * p[j + 1];\n            long long best = INF;\n            for (int k = i; k < j; ++k) {\n                // Both dp[i][k] and dpT[j][k + 1] are contiguous in memory along index k!\n                long long cost = dp[i][k] + dpT[j][k + 1] + outer_p * p[k + 1];\n                if (cost < best) best = cost;\n            }\n            dp[i][j] = best;\n            dpT[j][i] = best;\n        }\n    }\n    return dp[0][n - 1];\n}\n\n// 2. Burst Balloons: Guess the LAST balloon popped inside open interval (i, j)\nlong long max_coins_burst_balloons(const std::vector<int>& nums) {\n    // Pad with virtual boundary balloons of value 1 at both ends\n    std::vector<long long> a;\n    a.reserve(nums.size() + 2);\n    a.push_back(1);\n    for (int x : nums) if (x > 0) a.push_back(x);\n    a.push_back(1);\n\n    const int m = static_cast<int>(a.size());\n    std::vector<std::vector<long long>> dp(m, std::vector<long long>(m, 0));\n\n    // len is the distance j - i between open interval boundaries (minimum 2)\n    for (int len = 2; len < m; ++len) {\n        for (int i = 0; i + len < m; ++i) {\n            const int j = i + len;\n            const long long boundary_prod = a[i] * a[j];\n            long long best = 0;\n            for (int k = i + 1; k < j; ++k) {\n                best = std::max(best, dp[i][k] + dp[k][j] + boundary_prod * a[k]);\n            }\n            dp[i][j] = best;\n        }\n    }\n    return dp[0][m - 1];\n}\n\nint main() {\n  DESCRIBE(\"Interval DP: Matrix Chain Multiplication, Optimal BST & Polygon Triangulation — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes matrix_chain_multiplication state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes matrix_chain_multiplication core algorithmic transition (O(N^3))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies matrix_chain_multiplication edge cases and space bound (O(N^2))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
