    "starterCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Iterative Extended GCD: returns g = gcd(a, b) and sets x, y such that a*x + b*y = g\nint64_t ext_gcd(int64_t a, int64_t b, int64_t& x, int64_t& y) {  // TODO (Step 1): Implement ext_gcd(int64_t a, int64_t b, int64_t& x, int64_t& y)\n  // Maintain the Algorithmic Number Theory: Extended Euclidean Algorithm, Modular Inverse, CRT & Sieve of Eratosthenes invariant (O(N) time, O(N) space)\n  return 0;}\n\n// Modular inverse of a modulo m (works for ANY m where gcd(a, m) == 1)\nint64_t mod_inv(int64_t a, int64_t m) {  // TODO (Step 2): Implement mod_inv(int64_t a, int64_t m)\n  // Maintain the Algorithmic Number Theory: Extended Euclidean Algorithm, Modular Inverse, CRT & Sieve of Eratosthenes invariant (O(N) time, O(N) space)\n  return 0;}\n\n// Generalized Chinese Remainder Theorem for potentially non-coprime moduli:\n// Returns {r, lcm} such that X = r (mod lcm), or {-1, -1} if no solution exists\nstd::pair<int64_t, int64_t> crt_merge(int64_t r1, int64_t m1, int64_t r2, int64_t m2) {  // TODO (Step 3): Implement crt_merge(int64_t r1, int64_t m1, int64_t r2, int64_t m2)\n  // Maintain the Algorithmic Number Theory: Extended Euclidean Algorithm, Modular Inverse, CRT & Sieve of Eratosthenes invariant (O(N) time, O(N) space)\n  return {};}\n\n// Euler's O(N) Linear Sieve computing smallest prime factor spf[x] and totient phi[x]\nstruct LinearSieve {\n    std::vector<int> spf;\n    std::vector<int> phi;\n    std::vector<int> primes;\n\n    explicit LinearSieve(int n) : spf(n + 1, 0), phi(n + 1, 0) {\n        phi[1] = 1;\n        for (int i = 2; i <= n; ++i) {\n            if (spf[i] == 0) {\n                spf[i] = i;\n                phi[i] = i - 1;\n                primes.push_back(i);\n            }\n            for (int p : primes) {\n                if (p > spf[i] || 1LL * i * p > n) break;\n                spf[i * p] = p;\n                if (i % p == 0) {\n                    phi[i * p] = phi[i] * p; // p^2 divides i*p\n                    break;\n                } else {\n                    phi[i * p] = phi[i] * (p - 1); // gcd(i, p) == 1\n                }\n            }\n        }\n    }\n};\n\nint main() {\n  DESCRIBE(\"Algorithmic Number Theory: Extended Euclidean Algorithm, Modular Inverse, CRT & Sieve of Eratosthenes — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes LinearSieve state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes LinearSieve core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies LinearSieve edge cases and space bound (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n",
    "solutionCode": "#include <bits/stdc++.h>\n#include <codelab/dsa.hpp>\n#include <codelab/test.hpp>\nusing namespace std;\n// Iterative Extended GCD: returns g = gcd(a, b) and sets x, y such that a*x + b*y = g\nint64_t ext_gcd(int64_t a, int64_t b, int64_t& x, int64_t& y) {\n    x = 1; y = 0;\n    int64_t x1 = 0, y1 = 1, a1 = a, b1 = b;\n    while (b1 != 0) {\n        int64_t q = a1 / b1;\n        std::tie(x, x1) = std::make_tuple(x1, x - q * x1);\n        std::tie(y, y1) = std::make_tuple(y1, y - q * y1);\n        std::tie(a1, b1) = std::make_tuple(b1, a1 - q * b1);\n    }\n    return a1;\n}\n\n// Modular inverse of a modulo m (works for ANY m where gcd(a, m) == 1)\nint64_t mod_inv(int64_t a, int64_t m) {\n    int64_t x, y;\n    int64_t g = ext_gcd(a, m, x, y);\n    if (g != 1) return -1; // Inverse does not exist\n    return (x % m + m) % m;\n}\n\n// Generalized Chinese Remainder Theorem for potentially non-coprime moduli:\n// Returns {r, lcm} such that X = r (mod lcm), or {-1, -1} if no solution exists\nstd::pair<int64_t, int64_t> crt_merge(int64_t r1, int64_t m1, int64_t r2, int64_t m2) {\n    int64_t p, q;\n    int64_t g = ext_gcd(m1, m2, p, q);\n    if ((r2 - r1) % g != 0) return {-1, -1};\n\n    int64_t step = m2 / g;\n    __int128 diff = (r2 - r1) / g;\n    int64_t k = static_cast<int64_t>((diff % step * (p % step)) % step);\n    if (k < 0) k += step;\n\n    int64_t lcm = m1 * step;\n    int64_t r = static_cast<int64_t>((r1 + static_cast<__int128>(m1) * k) % lcm);\n    return {r, lcm};\n}\n\n// Euler's O(N) Linear Sieve computing smallest prime factor spf[x] and totient phi[x]\nstruct LinearSieve {\n    std::vector<int> spf;\n    std::vector<int> phi;\n    std::vector<int> primes;\n\n    explicit LinearSieve(int n) : spf(n + 1, 0), phi(n + 1, 0) {\n        phi[1] = 1;\n        for (int i = 2; i <= n; ++i) {\n            if (spf[i] == 0) {\n                spf[i] = i;\n                phi[i] = i - 1;\n                primes.push_back(i);\n            }\n            for (int p : primes) {\n                if (p > spf[i] || 1LL * i * p > n) break;\n                spf[i * p] = p;\n                if (i % p == 0) {\n                    phi[i * p] = phi[i] * p; // p^2 divides i*p\n                    break;\n                } else {\n                    phi[i * p] = phi[i] * (p - 1); // gcd(i, p) == 1\n                }\n            }\n        }\n    }\n};\n\nint main() {\n  DESCRIBE(\"Algorithmic Number Theory: Extended Euclidean Algorithm, Modular Inverse, CRT & Sieve of Eratosthenes — Guided C++20 Verification\", {\n    TEST(\"Step 1: initializes LinearSieve state and boundary invariants\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 2: executes LinearSieve core algorithmic transition (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n    TEST(\"Step 3: verifies LinearSieve edge cases and space bound (O(N))\", {\n      ASSERT_TRUE(true);\n    });\n  });\n  return CODELAB_TEST_EXIT_CODE();\n}\n"
